nodes.statement:
Let ${\mathcal L}$  be a non-local operator with variable order given by
\begin{equation} {\mathcal L} f(x)=\int_{\mathds R^d}\big(f(x+z)-f(x)-\langle\nabla f(x), z\rangle \mathds 1_{\{|z|\leqslant 1\}}\big)
\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz,\quad   f \in C_c^2(\mathds R^d),
\end{equation}
where $\alpha:\mathds R^d \rightarrow (0,2)$
is a measurable function such that
\begin{equation} \begin{split}
& 0<\alpha_1\leqslant \alpha(x) \leqslant \alpha_2<2  \quad \hbox{for }   x \in \mathds R^d,\\
& |\alpha(x)-\alpha(y)|\leqslant c_1(|x-y|^{\beta_1}\wedge 1)   \quad \hbox{for }   x,y\in \mathds R^d,
\end{split}
\end{equation}
for  some constants $c_1\in(0,\infty)$ and $\beta_1\in(0,1]$, and $\kappa:\mathds R^d\times \mathds R^d \rightarrow (0,\infty)$ is a measurable function satisfying
\begin{equation} \begin{split}
& \kappa(x,z)=\kappa(x,-z) \quad \hbox{for }  x,z \in \mathds R^d,\\
&  0<\kappa_1\leqslant \kappa(x,z)\leqslant \kappa_2<\infty \quad \hbox{for }   x,z\in \mathds R^d,\\
&  |\kappa(x,z)-\kappa(y,z)|\leqslant c_2(|x-y|^{\beta_2}\wedge 1)  \quad \hbox{for }   x,y,z\in \mathds R^d,
\end{split}
\end{equation}
for  some constants $c_2\in(0,\infty)$ and $\beta_2 \in (0,1]$.

For simplicity, throughout this paper we write ${\mathcal L} f(x)$ as
\begin{equation*}
{\mathcal L} f(x)=\frac{1}{2}\int_{\mathds R^d}
\big(f(x+z)+f(x-z)-2f(x)\big)\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz.
\end{equation*}

For fixed $y \in \mathds R^d$, define
\begin{equation} {\mathcal L}^y f(x):=\int_{\mathds R^d}\big(f(x+z)-f(x)-\langle\nabla f(x), z \rangle\mathds 1_{\{|z|\leqslant 1\}}\big)\frac{\kappa(y,z)}{|z|^{d+\alpha(y)}}\,dz.
\end{equation}

Throughout the paper,  we define for $ f:\mathds R^d\rightarrow \mathds R$,
\begin{equation*}
\delta_f(x;z):=f(x+z)+f(x-z)-2f(x), \quad \ x,z\in \mathds R^d.
\end{equation*}
\begin{equation*}
\delta_{p^y}(t,x;z):=p^y(t,x+z)+p^y(t,x-z)-2p^y(t,x),\quad t\in
(0,\infty),\ x,y,z\in \mathds R^d.
\end{equation*}

For every $x,z\in \mathds R^d$ with $|x-z|\leqslant 1$,
\begin{equation} \begin{split}
|x-z|^{-\alpha(z)}&=|x-z|^{-\alpha(x)}|x-z|^{\alpha(x)-\alpha(z)}\preceq |x-z|^{-\alpha(x)}\cdot \exp\left(\left|\log|x-z|\right|\left|\alpha(x)-\alpha(z)\right|\right)\\
&\preceq |x-z|^{-\alpha(x)}\cdot \exp\left(C\left|\log|x-z|\right|\cdot |x-z|^{\beta_0}\right)
\preceq |x-z|^{-\alpha(x)},
\end{split}
\end{equation}
where in the last inequality we have used
$$\sup_{z\in \mathds R^d: |z|\leqslant 1}\exp\big(C|\log
|z||\cdot|z|^{\beta_0}\big)<\infty.$$

Then, for all $t\in (0,1]$ and $x,z\in \mathds R^d$,
\begin{align*}
\frac{1}{(t^{{1}/{\alpha(z)}}+|x-z|)^{d+\alpha(z)}}& \preceq
\begin{cases}
|x-z|^{-d-\alpha(z)},& |x-z|\leqslant 1,\\
t^{-1-({d/\underline{\alpha}(x; t^{1/\alpha_2})})},&  |x-z|\leqslant t^{{1/\alpha(x)}},
\end{cases}
\\
&\preceq
\begin{cases}
|x-z|^{-d-\alpha(x)},& |x-z|\leqslant 1,\\
t^{-1-({d/\underline{\alpha}(x; t^{1/\alpha_2})})},&  |x-z|\leqslant t^{{1/\alpha(x)}}.
\end{cases}
\end{align*}

We only prove \eqref{l1-1-1} and \eqref{l1-1-2}, since
the proof of \eqref{l1-1-3} is similar and more direct. We denote $I_1(t,x,y,w)$ and $I_2(t,x,y,w)$ by $I_1$ and $I_2$, respectively.
Write
\begin{align*}
I_1&=\int_{\{|z|\leqslant t^{{1/\alpha(y)}}\}}
\big(t^{-{2}/{\alpha(y)}}|z|^2\big)\rho^{y,0}_1(t,w{+} z)\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz  +\int_{\{t^{{1/\alpha(y)}}<|z|\leqslant 1\}}\rho^{y,0}_1(t,w{+} z)\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
&=:I_{11}+I_{12}.
\end{align*}
We will divide the proof into the following three subcases.

{\bf Case (a): $0\leqslant |w| \leqslant 2t^{{1/\alpha(y)}}$.}



Since, by \eqref{e3-0}, \begin{equation} \rho^{y,0}_1(t,w{+} z)\preceq t^{-{d/\alpha(y)}}\quad \textrm{ for all } t\in(0,1]\textrm{ and }  y,z,w\in\mathds R^d,\end{equation} we have
\begin{align*}
I_{11}&\preceq t^{-{(d+2)}/{\alpha(y)}}\int_{\{|z|\leqslant t^{{1/\alpha(y)}}\}}
\frac{(1+|\log|z|)|z|^2}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
&\preceq(1+|\log t|)t^{-{(d+\overline\alpha(y;x))}/{\alpha(y)}} \preceq(1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),
\end{align*}
where in the last inequality we have used the fact that \begin{equation} t^{-{d/\alpha(y)}}\preceq \rho^{y,0}_1(t,w)
\quad \textrm{ when } |w|\leqslant 2t^{{1/\alpha(y)}}.\end{equation}

Applying \eqref{e:ond} and \eqref{e:one1} to
$I_{12}$ and $I_2$ again, we get
\begin{align*}
I_{12}&\preceq t^{-{d/\alpha(y)}}\int_{\{t^{{1/\alpha(y)}}<|z|\leqslant 1\}}
\frac{1+|\log |z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz \preceq(1+|\log t|)t^{-({d+\overline\alpha(y;x)})/{\alpha(y)}}\\
& \preceq(1+|\log t|)t^{1-({\overline
\alpha(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w)
\end{align*} and
\begin{align*}
I_2&\preceq  t^{-{d/\alpha(y)}}\int_{\{|z|> 1\}} \frac{1+\log
|z|}{|z|^{d+\alpha_1}}\,dz\preceq \rho^{y,0}_1(t,w).
\end{align*}

{\bf Case (b): $2t^{{1/\alpha(y)}}<|w|\leqslant {1}/{2}$.}

When $|w|>2t^{{1/\alpha(y)}}$ and $|z|\leqslant t^{{1/\alpha(y)}}$,
$
|w{+} z|\geqslant |w|-{|w|}/{2}\geqslant {|w|}/{2},
$
which along with \eqref{e3-0} implies that
\begin{equation} \begin{split}
\rho^{y,0}_0(t,w{+} z)&\preceq
\frac{1}{(t^{{1/\alpha(y)}}+|w{+} z|)^{d+\alpha(y)}}\preceq \frac{1}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}}.
\end{split}
\end{equation}
Therefore,
\begin{align*}
I_{11}&\preceq \frac{t^{1-{2}/{\alpha(y)}}}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}}
\int_{\{|z|\leqslant t^{{1/\alpha(y)}}\}}\frac{(1+|\log |z||)|z|^2}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
& \preceq (1+|\log t|)t^{1-({\overline\alpha(y;x)}/{\alpha(y)})}\frac{1}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}} \preceq (1+|\log t|)t^{1-({\overline
\alpha(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),
\end{align*}
where the last step is due to the fact that \begin{equation} \frac{1}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}} \preceq \rho^{y,0}_0(t,w)\quad
\textrm{ when }|w|>2t^{{1/\alpha(y)}}.\end{equation}

On the other hand, we have the following decomposition for $I_{12}$:
\begin{align*}
I_{12}&=\int_{\{
t^{{1/\alpha(y)}}<|z|\leqslant{|w|}/{2}\}}\rho^{y,0}_1(t,w{+} z)
\frac{1+|\log |z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz  + \int_{\{{|w|}/{2}\leqslant |z|\leqslant 1\}}\rho^{y,0}_1(t,w{+} z)
\frac{1+|\log |z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
&=:I_{121}+I_{122}.
\end{align*}
If $|z|\leqslant {|w|}/{2}$, then $|w{+} z|\geqslant {|w|}/{2}$,
and so \eqref{l2-1-7} still holds. Hence, we have
\begin{align*}
I_{121}&\preceq \frac{t}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}}
\int_{\{|z|>t^{{1/\alpha(y)}}\}}\frac{1+|\log |z||}{|z|^{d+\overline{\alpha}(y;x)}}\,dz\\
&\preceq (1+|\log t|)t^{-{\overline
\alpha(y;x)}/{\alpha(y)}}\frac{t}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}} \preceq (1+|\log t|)t^{1-({\overline
\alpha(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),
\end{align*} where the last step follows from \eqref{e:one-2}.
Meanwhile,
\begin{align*}
I_{122}&\preceq \frac{1+|\log|w||}{|w|^{d+\overline{\alpha}(y;x)}}\int_{\mathds R^d}\rho^{y,0}_1(t,w{+} z)\,dz\preceq \frac{1+|\log|w||}{|w|^{d+\overline{\alpha}(y;x)}}\\
&\preceq \frac{(1+|\log|w||)|w|^{\alpha(y)-\overline{\alpha}(y;x)}}{(t^{{1/\alpha(y)}}+|w|)^{d+\alpha(y)}}\preceq (1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),
\end{align*}
where the second inequality is due to \eqref{l3-1-1-00},
in the third inequality we have used the fact that $$|w|^{-d-\alpha(y)}\preceq
(t^{{1/\alpha(y)}}+|w|)^{-d-\alpha(y)}\quad \textrm{ when } 2t^{{1/\alpha(y)}}<|w|\leqslant {1}/{2},$$ and the fourth
inequality follows from
$$ (1+|\log|w||)|w|^{\alpha(y)-\overline{\alpha}(y;x)}\preceq (1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}
\quad\textrm{ when }2t^{{1/\alpha(y)}}<|w|\leqslant {1}/{2}.$$
Combining with all the estimates above, we obtain
$$I_1\preceq (1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w).$$

Furthermore, note that if $|w|\leqslant {1}/{2}$ and $|z|>1$, then
$
|w{+} z|\geqslant |z|-|w|\geqslant 2|w|-|w|=|w|.
$
Therefore, for every $y,z,w\in\mathds R^d$ and $t\in(0,1]$ with $|z|>1$ and $2t^{{1/\alpha(y)}}\leqslant |w|\leqslant{1}/{2}$,
\begin{align*}
\rho^{y,0}_0(t,w{+} z)& \preceq
\begin{cases}
|w|^{-d-\alpha(y)}, \ &\ |w{+} z|\leqslant 1,\\
|w|^{-d-\alpha_1},\ &\  |w{+} z|> 1
\end{cases}\\
&\preceq |w|^{-d-\alpha(y)},
\end{align*}
which implies that
\begin{align*}
I_2&\preceq \frac{t}{|w|^{d+\alpha(y)}}
\int_{\{|z|\geqslant 1\}} \frac{1+\log |z|}{|z|^{d+\alpha_1}}\,dz\preceq
\frac{t}{|w|^{d+\alpha(y)}}\preceq \rho^{y,0}_1(t,w).
\end{align*}

(i)
Applying the mean value theorem to the function $r\mapsto a^r$, we find that for every $x,y,z \in \mathds R^d$ with
$|z|>0$,
\begin{equation} \begin{split}
&\bigg|\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}-\frac{\kappa(y,z)}{|z|^{d+\alpha(y)}}\bigg|\\
&\preceq |\alpha(x)-\alpha(y)|\bigg(\frac{|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\mathds 1_{\{|z|\leqslant 1\}}+
\frac{\log|z|}{|z|^{d+\underline{\alpha}(y;x)}}\mathds 1_{\{|z|> 1\}}\bigg)  +\frac{|\kappa(x,z)-\kappa(y,z)|}{|z|^{d+\alpha(y)}}\\
&\preceq \big(|x-y|^{\beta_0}\wedge
1\big)\bigg(\frac{1+|\log|z||}{|z|^{d+\overline
\alpha(y;x)}}\mathds 1_{\{|z|\leqslant 1\}}+ \frac{1+\log|z|}{|z|^{d+\underline
\alpha(y;x)}}\mathds 1_{\{|z|> 1\}}\bigg),
\end{split}
\end{equation}
where in the last inequality we have used \eqref{e1-2}, \eqref{e1-3} and the
fact that
\begin{equation*}
\frac{1}{|z|^{d+\alpha(y)}}\preceq \frac{1}{|z|^{d+\overline
\alpha(y;x)}}\mathds 1_{\{|z|\leqslant 1\}}+ \frac{1}{|z|^{d+\underline
\alpha(y;x)}}\mathds 1_{\{|z|> 1\}}.
\end{equation*}
Combining \eqref{e:pp} with \eqref{e2-3}, we can obtain that
\begin{align*}
 \big|\big( {\mathcal L}^x- {\mathcal L}^y\big)p^y(t,w)\big|
& \preceq
\big(|x-y|^{\beta_0}\wedge 1\big) \int_{\mathds R^d}|\delta_{p^y}(t,w;z)|\bigg(
\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\mathds 1_{\{|z|\leqslant 1\}}+\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(y;x)}}\mathds 1_{\{|z|> 1\}}\bigg)\,dz\\
&\preceq\big(|x-y|^{\beta_0}\wedge 1\big)\cdot \big(I_1(t,x,y,w)+I_2(t,x,y,w)+\rho^{y,0}_1(t,w)I_3(t,x,y)\big),
\end{align*}
where in the second inequality we have used \eqref{p1-1-2}, and $I_1$, $I_2$ and $I_3$ are defined in \eqref{l1-1-0}.
Hence, Lemma \ref{l1-1} yields that
\begin{equation} \begin{split}
&\big|\big( {\mathcal L}^x- {\mathcal L}^y\big)p^y(t,w)\big|\\
&\preceq  \!\big(|x-y|^{\beta_0}\wedge 1\big) \!\cdot\!
\begin{cases}
(1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\rho^{y,0}_0(t,w),\ \ &\ |w|\leqslant {1}/{2},\\
\big(1+|\log |w||+(1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\big)\rho^{y,0}_0(t,w),\ \
&\ |w|>{1}/{2}.
\end{cases}
\end{split}
\end{equation}
Note that due to \eqref{e1-3},
\begin{equation*}
\overline{\alpha}(y;x)\leqslant \alpha(y)+c_0|x-y|^{\beta_0}\leqslant
\alpha(y)+c_0R_1^{\beta_0}\quad\textrm{ for all } x,y\in\mathds R^d\textrm{ with }|x-y|\leqslant R_1.
 \end{equation*}
Therefore, choosing $R_1\in(0,{1}/{2})$ small enough such that
$c_0R_1^{\beta_0} /\alpha_1 < \gamma$, we have
\begin{equation*}
(1+|\log t|)t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}\preceq t^{-\gamma}\quad\textrm{ when }|x-y|\leqslant R_1.
\end{equation*}
This, along with \eqref{l1-2-2}, immediately implies \eqref{l1-2-1}.


Estimate  \eqref{l1-2-1a} follows from \eqref{l1-2-1} by taking $w=x-y$.

\smallskip

(2) Now we suppose the general case that $\kappa(x,z)$ may depend on $z$. We still define $J_1$ and $J_2$ by those in \eqref{l2-1-3a}. It is not
difficult to verify that \eqref{e:ref1} also holds for this case.
On the other hand, according to \eqref{p1-1-2}, it holds that
\begin{equation} \begin{split}
J_1&\preceq \int_{\{|z|\leqslant {R_1}/{2}\}}\big[(t^{-{2}/{\alpha(y)}}|z|^2)\wedge 1\big]\cdot\rho^{y,0}_1(t,x-y\pm z)\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&\quad +\rho_1^{y,0}(t,x-y)\int_{\{|z|\leqslant {R_1}/{2}\}}\big[(t^{-{2}/{\alpha(y)}}|z|^2)\wedge 1\big]\cdot\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&\preceq\frac{t^{1-{2}/{\alpha(y)}}}{|x-y|^{d+\alpha_1}}\int_{\{|z|\leqslant
t^{{1/\alpha(y)}}\}}|z|^{2-d-\alpha(x)}\,dz  +
\frac{t}{|x-y|^{d+\alpha_1}}\int_{\{t^{{1/\alpha(y)}}\leqslant |z|\leqslant {R_1}/{2}\}}|z|^{-d-\alpha(x)}\,dz\\
&\quad + \frac{t}{|x-y|^{d+\alpha_1}}
\int_{\{|z|\leqslant {R_1}/{2}\}}\big[(t^{-{2}/{\alpha(y)}}|z|^2)\wedge 1\big]|z|^{-d-\alpha(x)}\,dz\\
&\preceq \frac{t^{1-({\overline{\alpha}(y;x)}/{\alpha(y)})}}{|x-y|^{d+\alpha_1}}\leqslant  \frac{t^{1-(\alpha_2/\alpha_1)}}{|x-y|^{d+\alpha_1}}.
\end{split}
\end{equation}
Here the second step follows from
\begin{equation*}
\rho^{y,0}_0(t,x-y+ z)\preceq \frac{1}{|x-y|^{d+\alpha_1}}\quad\textrm{
when } |x-y|> R_1\textrm{ and }|z|\leqslant {R_1}/{2},
\end{equation*}
which is due to the fact that for $ |x-y|> R_1$ and $ |z|\leqslant {R_1}/{2}$
$$|x-y+ z| \geqslant |x-y|-|z|\geqslant  {|x-y|}/{2}\geqslant
{R_1}/{2}\geqslant C_0t^{{1/\alpha(y)}}.$$

Note also that \eqref{l2-1-4} is still true for this case. Combining all the estimates above, we obtain
\begin{align*}
|q_0(t,x,y)|&\preceq
| {\mathcal L}^x p^y(t,x-y)|+| {\mathcal L}^y p^y(t,x-y)| \preceq J_1+J_2+| {\mathcal L}^yp^y(t,x-y)|\preceq t^{1-({\alpha_2}/{\alpha_1})}\rho_0^{y,0}(t,x-y),
\end{align*}
where in the last step we used the fact that $t^{-{\overline{\alpha}(y;x)}/{\alpha(y)}}\leqslant t^{-{\alpha_2}/{\alpha_1}}$ for all $t \in (0,1].$
Thus, the second case of \eqref{l2-1-1} is proved.

(1) We first suppose that $\kappa(x,z)$ is independent of $z$.

{\bf Case (a): $|x-y|\leqslant t^{{1}/{\alpha(y)}}.$}

According to \eqref{l1-2-1a}, we can choose $0<\gamma<{\beta_0}/{\alpha_2}$ and adjust the constants properly to get that
\begin{equation} \begin{split}
|q_0(t,x-y)|&\preceq \rho^{y,\beta_0}_{-\gamma}(t,x-y)\preceq t^{-\gamma}|x-y|^{\beta_0}\cdot\rho^{y,0}_{0}(t,x-y)\\
&\preceq t^{({\beta_0}/{\alpha_2})-\gamma}\rho^{y,0}_0(t,x-y)\preceq \rho^{y,0}_0(t,x-y)\preceq t^{-({d}/{\alpha(y)})-1},
\end{split}
\end{equation}
where in the third inequality we have used the fact that $|x-y|\leqslant t^{{1}/{\alpha(y)}}\leqslant t^{{1}/{\alpha_2}}$, and the
fourth inequality follows from $\gamma<{\beta_0}/{\alpha_2}$.

{\bf Case (b): $|x-y|>t^{{1}/{\alpha(y)}}.$}

By \eqref{e2-3}, it holds that
\begin{equation} \begin{split}
| {\mathcal L}^x p^y(t,\cdot)(x-y)|&
\preceq \int_{\{|z|\leqslant {|x-y|}/{2}\}}\left|
\delta_{p^y}\left(t,x-y;z\right)\right|\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&\quad +\int_{\{|z|> {|x-y|}/{2}\}}\left|
\delta_{p^y}\left(t,x-y;z\right)\right|\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&=:J_1+J_2.
\end{split}
\end{equation}
Then, using the mean value theorem, we have
\begin{align*}
J_1&\preceq \int_{\{|z|\leqslant {|x-y|}/{2}\}}
\left|\nabla^2 p^y(t,x-y+\theta_{x,y,z} z)\right|\cdot |z|^2\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&\preceq \int_{\{|z|\leqslant {|x-y|}/{2}\}}
\frac{t}{\left(t^{{1}/{\alpha(y)}}+|x-y+\theta_{x,y,z} z|\right)^{d+\alpha(y)+2}}
\cdot |z|^{2-d-\alpha(x)}\,dz\\
&\preceq \frac{t}{\left(t^{{1}/{\alpha(y)}}+|x-y|\right)^{d+\alpha(y)+2}}
\int_{\{|z|\leqslant {|x-y|}/{2}\}} |z|^{2-d-\alpha(x)}\,dz\\
&\preceq \frac{|x-y|^{\alpha(y)}}{|x-y|^{d+\alpha(y)+2}}\cdot |x-y|^{2-\alpha(x)}\preceq \frac{1}{|x-y|^{d+\alpha(x)}},
\end{align*}
where in the first inequality  $\theta_{x,y,z}$ is a constant depending on $x,y,z$ such that
$|\theta_{x,y,z}|\leqslant 1$, in the second inequality we have used \eqref{p1-1-1}, the third inequality follows
from the fact that $|x-y+\theta_{x,y,z} z|\geqslant |x-y|-|z|\geqslant {|x-y|}/{2}$, and the fourth inequality is due to
the fact that $t\leqslant |x-y|^{\alpha(y)}$.


On the other hand,
by \eqref{p1-1-2} and the fact that $|z|>{|x-y|}/{2}\geqslant t^{{1}/{\alpha(y)}}/2$, we have
$ \left|\delta_{p^y}(t,x-y;z)\right|\preceq \rho^{y,0}_1(t,x-y\pm z)+\rho^{y,0}_1(t,x-y),$ and so \begin{align*}
J_2&\preceq  \int_{\{|z|>{|x-y|}/{2}\}}\!\!
\rho^{y,0}_1(t,x-y\pm z)\frac{1}{|z|^{d+\alpha(x)}}\,dz +
\rho^{y,0}_1(t,x-y)\int_{\{|z|>{|x-y|}/{2}\}}\!\!
\frac{1}{|z|^{d+\alpha(x)}}\,dz=:J_{21}+J_{22}.
\end{align*}
It holds that
\begin{align*}
J_{21}&\preceq \frac{1}{|x-y|^{d+\alpha(x)}} \int_{\{|z|>{|x-y|}/{2}\}}\rho^{y,0}_1(t,x-y\pm z)\,dz\preceq \frac{1}{|x-y|^{d+\alpha(x)}}\int \rho^{y,0}_1(t,x-y\pm z)\,dz\preceq \frac{1}{|x-y|^{d+\alpha(x)}},
\end{align*}
where in the first inequality we have used following fact
$$ \frac{1}{|z|^{d+\alpha(x)}}\preceq \frac{1}{|x-y|^{d+\alpha(x)}}\quad\textrm{ for } |z|>{|x-y|}/{2},$$
and the last inequality follows from \eqref{l3-1-1-00}.
Furthermore, it is easy to verify that
\begin{align*}
J_{22}&\preceq \rho^{y,0}_1(t,x-y)
\int_{\{|z|>{|x-y|}/{2}\}}\frac{1}{|z|^{d+\alpha(x)}}\, dz\preceq \frac{t}{|x-y|^{d+\alpha(x)+\alpha(y)}}\preceq \frac{1}{|x-y|^{d+\alpha(x)}},
\end{align*} where in the last inequality we used $|x-y|\leqslant t^{{1}/{\alpha(y)}}$.

Combining all these estimates above, we arrive at
$$ \left| {\mathcal L}^xp^y(t,\cdot)(x-y)\right|\preceq \frac{1}{|x-y|^{d+\alpha(x)}}.$$
Following the same arguments as above, we also have
$$ \left| {\mathcal L}^yp^y(t,\cdot)(x-y)\right|\preceq \frac{1}{|x-y|^{d+\alpha(y)}}.$$
Hence,
\begin{align*}
|q_0(t,x,y)|&\preceq
\left| {\mathcal L}^x p^y(t,\cdot)(x-y)\right|+\left| {\mathcal L}^yp^y(t,\cdot)(x-y)\right|\preceq \frac{1}{|x-y|^{d+\alpha(x)}}+\frac{1}{|x-y|^{d+\alpha(y)}},
\end{align*}
from which we can get \eqref{p2-1-1} immediately.

{\bf Case (a): $|x-y|\leqslant t^{{1}/{\alpha(y)}}.$}

According to \eqref{l1-2-1a}, we can choose $0<\gamma<{\beta_0}/{\alpha_2}$ and adjust the constants properly to get that
\begin{equation} \begin{split}
|q_0(t,x-y)|&\preceq \rho^{y,\beta_0}_{-\gamma}(t,x-y)\preceq t^{-\gamma}|x-y|^{\beta_0}\cdot\rho^{y,0}_{0}(t,x-y)\\
&\preceq t^{({\beta_0}/{\alpha_2})-\gamma}\rho^{y,0}_0(t,x-y)\preceq \rho^{y,0}_0(t,x-y)\preceq t^{-({d}/{\alpha(y)})-1},
\end{split}
\end{equation}
where in the third inequality we have used the fact that $|x-y|\leqslant t^{{1}/{\alpha(y)}}\leqslant t^{{1}/{\alpha_2}}$, and the
fourth inequality follows from $\gamma<{\beta_0}/{\alpha_2}$.

{\bf Case (b): $|x-y|>t^{{1}/{\alpha(y)}}.$}

By \eqref{e2-3}, it holds that
\begin{equation} \begin{split}
| {\mathcal L}^x p^y(t,\cdot)(x-y)|&
\preceq \int_{\{|z|\leqslant {|x-y|}/{2}\}}\left|
\delta_{p^y}\left(t,x-y;z\right)\right|\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&\quad +\int_{\{|z|> {|x-y|}/{2}\}}\left|
\delta_{p^y}\left(t,x-y;z\right)\right|\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&=:J_1+J_2.
\end{split}
\end{equation}
Then, using the mean value theorem, we have
\begin{align*}
J_1&\preceq \int_{\{|z|\leqslant {|x-y|}/{2}\}}
\left|\nabla^2 p^y(t,x-y+\theta_{x,y,z} z)\right|\cdot |z|^2\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&\preceq \int_{\{|z|\leqslant {|x-y|}/{2}\}}
\frac{t}{\left(t^{{1}/{\alpha(y)}}+|x-y+\theta_{x,y,z} z|\right)^{d+\alpha(y)+2}}
\cdot |z|^{2-d-\alpha(x)}\,dz\\
&\preceq \frac{t}{\left(t^{{1}/{\alpha(y)}}+|x-y|\right)^{d+\alpha(y)+2}}
\int_{\{|z|\leqslant {|x-y|}/{2}\}} |z|^{2-d-\alpha(x)}\,dz\\
&\preceq \frac{|x-y|^{\alpha(y)}}{|x-y|^{d+\alpha(y)+2}}\cdot |x-y|^{2-\alpha(x)}\preceq \frac{1}{|x-y|^{d+\alpha(x)}},
\end{align*}
where in the first inequality  $\theta_{x,y,z}$ is a constant depending on $x,y,z$ such that
$|\theta_{x,y,z}|\leqslant 1$, in the second inequality we have used \eqref{p1-1-1}, the third inequality follows
from the fact that $|x-y+\theta_{x,y,z} z|\geqslant |x-y|-|z|\geqslant {|x-y|}/{2}$, and the fourth inequality is due to
the fact that $t\leqslant |x-y|^{\alpha(y)}$.


On the other hand,
by \eqref{p1-1-2} and the fact that $|z|>{|x-y|}/{2}\geqslant t^{{1}/{\alpha(y)}}/2$, we have
$ \left|\delta_{p^y}(t,x-y;z)\right|\preceq \rho^{y,0}_1(t,x-y\pm z)+\rho^{y,0}_1(t,x-y),$ and so \begin{align*}
J_2&\preceq  \int_{\{|z|>{|x-y|}/{2}\}}\!\!
\rho^{y,0}_1(t,x-y\pm z)\frac{1}{|z|^{d+\alpha(x)}}\,dz +
\rho^{y,0}_1(t,x-y)\int_{\{|z|>{|x-y|}/{2}\}}\!\!
\frac{1}{|z|^{d+\alpha(x)}}\,dz=:J_{21}+J_{22}.
\end{align*}
It holds that
\begin{align*}
J_{21}&\preceq \frac{1}{|x-y|^{d+\alpha(x)}} \int_{\{|z|>{|x-y|}/{2}\}}\rho^{y,0}_1(t,x-y\pm z)\,dz\preceq \frac{1}{|x-y|^{d+\alpha(x)}}\int \rho^{y,0}_1(t,x-y\pm z)\,dz\preceq \frac{1}{|x-y|^{d+\alpha(x)}},
\end{align*}
where in the first inequality we have used following fact
$$ \frac{1}{|z|^{d+\alpha(x)}}\preceq \frac{1}{|x-y|^{d+\alpha(x)}}\quad\textrm{ for } |z|>{|x-y|}/{2},$$
and the last inequality follows from \eqref{l3-1-1-00}.
Furthermore, it is easy to verify that
\begin{align*}
J_{22}&\preceq \rho^{y,0}_1(t,x-y)
\int_{\{|z|>{|x-y|}/{2}\}}\frac{1}{|z|^{d+\alpha(x)}}\, dz\preceq \frac{t}{|x-y|^{d+\alpha(x)+\alpha(y)}}\preceq \frac{1}{|x-y|^{d+\alpha(x)}},
\end{align*} where in the last inequality we used $|x-y|\leqslant t^{{1}/{\alpha(y)}}$.

Combining all these estimates above, we arrive at
$$ \left| {\mathcal L}^xp^y(t,\cdot)(x-y)\right|\preceq \frac{1}{|x-y|^{d+\alpha(x)}}.$$
Following the same arguments as above, we also have
$$ \left| {\mathcal L}^yp^y(t,\cdot)(x-y)\right|\preceq \frac{1}{|x-y|^{d+\alpha(y)}}.$$
Hence,
\begin{align*}
|q_0(t,x,y)|&\preceq
\left| {\mathcal L}^x p^y(t,\cdot)(x-y)\right|+\left| {\mathcal L}^yp^y(t,\cdot)(x-y)\right|\preceq \frac{1}{|x-y|^{d+\alpha(x)}}+\frac{1}{|x-y|^{d+\alpha(y)}},
\end{align*}
from which we can get \eqref{p2-1-1} immediately.

(1) We first consider the case that $\kappa(x,z)$ is independent of $z$. Let $R_1:=R_1(\alpha,\kappa,\gamma)$ be a positive constant to be determined later. The proof is split into the following five different cases.

{\bf Case (a): $|x-x'|>R_1$.}

By \eqref{l2-1-2} and the condition $\beta_0>\alpha_2\theta$, it holds that
\begin{align*} |q_0(t,x,y)-q_0(t,x',y)|
&\leqslant |q_0(t,x,y)|+|q_0(t,x',y)|\preceq \rho_{-\gamma}^{y,\beta_0}(t,x-y)+\rho_{-\gamma}^{y,\beta_0}(t,x'-y)\\
&\preceq \big(|x-x'|^{{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}}\wedge1\big)\big(\rho_{-\gamma}^{y,\beta_0}(t,x-y)+\rho_{-\gamma}^{y,\beta_0}(t,x'-y)\big).\end{align*}



{\bf Case (b): $C_0t^{1/\alpha(y)}\leqslant |x-x'|\leqslant R_1$ for some small
constant $C_0>0$.}


According to \eqref{l2-1-2} again, we have
\begin{align*} |q_0(t,x,y)|\preceq& \rho_{-\gamma}^{y,\beta_0}(t,x-y)\preceq t^{{(\beta_0-\alpha(x)\theta)}/{\alpha(x)}} \rho_{-\gamma+\theta-({\beta_0}/{\alpha(x)})}^{y,\beta_0}(t,x-y) \\
\preceq&|x-x'|^{{{\alpha(y)(\beta_0-\alpha(x)\theta)}/{\alpha(x)}}} \rho_{-\gamma+\theta-({\beta_0}/{\alpha(x)})}^{y,\beta_0}(t,x-y) \\
\preceq&|x-x'|^{{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}} \rho_{-\gamma+\theta-({\beta_0}/{\alpha(x)})}^{y,\beta_0}(t,x-y),  \end{align*}
where the third inequality is due to $t\preceq |x-x'|^{\alpha(y)}$.
Then
\begin{align*}&|q_0(t,x,y)-q_0(t,x',y)|\\
&\leqslant |q_0(t,x,y)|+|q_0(t,x',y)|\\
&\preceq |x-\!x'|^{{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}} \! \rho_{-\gamma+\theta-({\beta_0}/{\alpha(x)})}^{y,\beta_0}(t,x-y)  +
|x-\!x'|^{{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x')}}}\!
\rho_{-\gamma+\theta-({\beta_0}/{\alpha(x')})}^{y,\beta_0}(t,x'\!-y)\\
&\preceq |x-\!x'|^{{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}}\Big(
\rho_{-\gamma+\theta-({\beta_0}/{\alpha(x)})}^{y,\beta_0}(t,x\!-y)+
\rho_{-\gamma+\theta-({\beta_0}/{\alpha(x')})}^{y,\beta_0}(t,x'\!-y)\Big).\end{align*}
Here in the last inequality we have used the fact that for $ x,x'\in
\mathds R^d$ with $|x-x'|\leqslant R_1,$
\begin{equation} |x-x'|^{{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x')}}}\preceq
|x-x'|^{{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}},
\end{equation}
which can be verified by following the argument of \eqref{l3-1-1a}.

Next, we mainly treat the case that $|x-x'|\leqslant C_0t^{1/\alpha(y)}$,
which we divide into three cases.

{\bf Case (c): $|x-x'|\leqslant C_0t^{1/\alpha(y)}$ and $|x-y|\geqslant R_1$.}

By the definition of $q_0(t,x,y)$,
\begin{equation} \begin{split}
 |q_0(t,x,y)-q_0(t,x',y)|
&=\frac{1}{2}\bigg|\int_{\mathds R^d} \delta_{p^y}(t,x-y;z)\bigg(\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}-\frac{\kappa(y,z)}{|z|^{d+\alpha(y)}} \bigg)\,dz\\
&\qquad\quad-\int_{\mathds R^d} \delta_{p^y}(t,x'-y;z)\bigg(\frac{\kappa(x',z)}{|z|^{d+\alpha(x')}}-\frac{\kappa(y,z)}{|z|^{d+\alpha(y)}} \bigg)\,dz\bigg|\\
&\leqslant \frac{1}{2}\int_{\mathds R^d} |\delta_{p^y}(t,x-y;z)-\delta_{p^y}(t,x'-y;z)| \bigg|\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}-\frac{\kappa(y,z)}{|z|^{d+\alpha(y)}} \bigg|\,dz\\
&\quad+ \frac{1}{2}\int_{\mathds R^d} |\delta_{p^y}(t,x'-y;z)| \bigg|\frac{\kappa(x',z)}{|z|^{d+\alpha(x')}}-\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}} \bigg|\,dz\\
&=:J_1+J_2.
\end{split}
\end{equation}


Note that \begin{equation} \begin{split} \delta_{p^y}(t,x;z)=&p^y(t,x+z)+p^y(t,x-z)-2p^y(t,x)\\
=&\int_0^1 \frac{d}{d\theta}\Big(p^y(t,x+\theta z)+p^y(t,x-\theta z)\Big)\,d\theta\\
=&\int_0^1 \langle \nabla p^y(t,x+\theta z)-\nabla p^y(t,x-\theta z),z\rangle \,d\theta\\
=&\int_0^1 \Big\langle \int_{-1}^1 \frac{d}{d \theta'}\left(\nabla p^y(t,x+\theta'\theta z)\right)d\theta',z \Big\rangle \,d\theta\\
=&\int_0^1\int_{-1}^1 \nabla^2 p^y(t,x+\theta'\theta z)(\theta z, z)d\theta'\,d\theta,\end{split}\end{equation}
and so
\begin{align*}  \delta_{p^y}(t,x;z)-\delta_{p^y}(t,x';z)
&=\int_0^1\int_{-1}^1 \big(\nabla^2 p^y(t,x+\theta'\theta z)- \nabla^2 p^y(t,x'+\theta'\theta z)\big)(\theta z, z)\,d\theta'\,d\theta\\
&=\int_0^1\int_{-1}^1\int_0^1  \frac{d}{d\theta''}\Big(\nabla^2 p^y(t,x'+\theta''(x-x')+\theta'\theta z)\Big)
(\theta z, z)\,d\theta''d\theta'\,d\theta\\
&=\int_0^1\int_{-1}^1\int_0^1  \nabla^3 p^y(t,x'+\theta''(x-x')+\theta'\theta z)
(x-x',\theta z, z)\,d\theta''d\theta'\,d\theta,\end{align*} which implies that
\begin{align*}
 |\delta_{p^y}(t,x;z)-\delta_{p^y}(t,x';z) |
&\leqslant \Big(\int_0^1\int_{-1}^1\int_0^1 |\nabla^3 p^y(t,x'+\theta''(x-x')+\theta'\theta z)|\,\,d\theta''d\theta'\,d\theta\Big)
\cdot |z|^2|x-x'|.
\end{align*}
For every $x,x',z\in\mathds R^d$ with $|x-x'|\leqslant C_0 t^{{1/\alpha(y)}}$, $|x|\geqslant cR_1$, $|x'|\geqslant cR_1$ and $|z|\leqslant {cR_1}/{4}$
for $C_0$ small enough, there exists a constant $c'>0$ such that for every $\theta\in(0,1)$, $\theta'\in(-1,1)$ and $\theta''\in(0,1)$, we have
$|x'+\theta''(x-x')+\theta'\theta z|\geqslant c'|x'|\geqslant c''R_1,$ which along with \eqref{p1-1-1} yields that
$$|\nabla^3 p^y(t,x'+\theta''(x-x')+\theta'\theta z)| \preceq \frac{t}{|x'|^{d+\alpha(y)+3}}.$$ Combining with all the estimates above, we arrive at that
for $|x-x'|\leqslant C_0t^{1/\alpha(y)}$, $|x|\geqslant cR_1$, $|x'|\geqslant cR_1$ and $|z|\leqslant {cR_1}/{4}$,
\begin{equation} |\delta_{p^y}(t,x;z)-\delta_{p^y}(t,x';z) |\preceq \frac{t|z|^2|x-x'|}{|x'|^{d+\alpha(y)+3}}.
   \end{equation}


Since $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}\leqslant C_0$, $|x'-y|\geqslant cR_1$ holds for some constant $c>0$.
By taking $x=x-y$ and $x'=x'-y$ in \eqref{e:conpr1}, we obtain that for all $z\in\mathds R^d$ with $|z|\leqslant {cR_1}/{4}$,
\begin{equation} |\delta_{p^y}(t,x-y;z)-\delta_{p^y}(t,x'-y;z) |\preceq \frac{t|z|^2|x-x'|}{|x'-y|^{d+\alpha(y)+3}}.  \end{equation}

Let \begin{equation} \begin{split}
J_1=&\frac{1}{2}\int_{\{|z|\leqslant {cR_1}/{4}\}} |\delta_{p^y}(t,x-y;z)-\delta_{p^y}(t,x'-y;z)| \bigg|\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}-\frac{\kappa(y,z)}{|z|^{d+\alpha(y)}} \bigg|\,dz\\
&+ \frac{1}{2}\int_{\{|z|> {cR_1}/{4}\}} |\delta_{p^y}(t,x-y;z)-\delta_{p^y}(t,x'-y;z)| \bigg|\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}-\frac{\kappa(y,z)}{|z|^{d+\alpha(y)}} \bigg|\,dz\\
=&:J_{11}+J_{12}.
 \end{split}
\end{equation}
 By \eqref{e:conpr2},
 \begin{align*}J_{11}\preceq &|x-x'|\frac{t}{|x'-y|^{d+\alpha(y)+3}} \int_{\{|z|\leqslant {cR_1}/{4}\}}\bigg( \frac{|z|^2}{|z|^{d+\alpha(x)}}+\frac{|z|^2}{|z|^{d+\alpha(y)}} \bigg)\,dz\\
 \preceq& |x-x'|\frac{t}{|x'-y|^{d+\alpha(y)+3}} \preceq |x-x'|\frac{1}{|x'-y|^{d+\alpha_1}},
 \end{align*} where the last inequality is due to $|x'-y|>cR_1$ and $t\leqslant 1$.
On the other hand, according to \eqref{r1-1-1}, we have for any $x,y\in\mathds R^d$ with $|x-y|>R_1$,
\begin{equation} \begin{split}
&\int_{\{|z|>{cR_1}/{4}\}} \rho_1^{y,0}(t,x-y\pm z) \frac{1}{|z|^{d+\alpha (x)}}\,dz \preceq \frac{1}{|x-y|^{d+\alpha_1}},\\
&\int_{\{|z|>{cR_1}/{4}\}} \rho_1^{y,0}(t,x-y) \frac{1}{|z|^{d+\alpha (x)}}\,dz \preceq \frac{1}{|x-y|^{d+\alpha_1}}.
\end{split}
\end{equation}
Combining \eqref{p1-1-4} with \eqref{l3-1-3b} and the fact that $|z|>{cR_1}/{4}$ implies $|z|>C_1t^{{1/\alpha(y)}}$, we arrive at
\begin{align*}
J_{12}&\preceq t^{-{1/\alpha(y)}}|x-x'| \int_{\{|z|>{cR_1}/{4}\}}\Big(\rho_1^{y,0}(t,x-y\pm z)+\rho_1^{y,0}(t,x-y)\\
&\qquad \qquad\qquad\qquad +\rho_1^{y,0}(t,x'-y\pm z)+\rho_1^{y,0}(t,x'-y)\Big)
\bigg(\frac{1}{|z|^{d+\alpha(x)}}+\frac{1}{|z|^{d+\alpha(y)}} \bigg)\,dz\\
&\preceq t^{-{1/\alpha(y)}}|x-x'| \left( \frac{1}{|x-y|^{d+\alpha_1}}+
\frac{1}{|x'-y|^{d+\alpha_1}} \right). \end{align*} By both of the
estimates above, we obtain that
 \begin{align*}J_1&\preceq t^{-{1/\alpha(y)}}|x-x'| \big( \rho_0^{y,0}(t,x-y)+\rho_0^{y,0}(t,x'-y)\big)\preceq  |x-x'| \big( \rho_{-{1/\alpha(y)}}^{y,\beta_0}(t,x-y)+\rho_{-{1/\alpha(y)}}^{y,\beta_0}(t,x'-y)\big), \end{align*}
where the last inequality follows from the facts that $|x-y|\geqslant cR_1$ and $|x'-y|\geqslant c R_1$.


Let \begin{equation} \begin{split}
J_2=&\int_{\{|z|\leqslant {cR_1}/{4}\}} |\delta_{p^y}(t,x'-y;z)| \bigg|\frac{\kappa(x',z)}{|z|^{d+\alpha(x')}}-\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}} \bigg|\,dz\\
&+ \int_{\{|z|> {cR_1}/{4}\}} |\delta_{p^y}(t,x'-y;z)| \bigg|\frac{\kappa(x',z)}{|z|^{d+\alpha(x')}}-\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}} \bigg|\,dz\\
=&:J_{21}+J_{22}.
\end{split}
\end{equation}
Since $|x'-y|>cR_1$, by \eqref{e:conpr0} and \eqref{p1-1-1}, we find that for any $|z|<{cR_1}/{4} $,
\begin{align*}|\delta_{p^y}(t,x'-y;z)|&\leqslant |z|^2\int_0^1\int_{-1}^1 |\nabla^2 p^y(t,x'-y+\theta'\theta z)|\,d\theta'\,d\theta \preceq |z|^2 \frac{ t}{ |x'-y|^{d+\alpha(y)+2}}.\end{align*}
 Thus,
 due to \eqref{e:pp},
 \begin{align*}J_{21} \preceq& |x-x'|^{\beta_0} \frac{t}{|x'-y|^{d+\alpha(y)+2}}\int_{\{|z|\leqslant {cR_1}/{4}\}} \!\!\frac{1+|\log |z||}{|z|^{d+\overline\alpha(x;x')}}|z|^2\,dz
 \preceq  |x-x'|^{\beta_0} \frac{1}{|x'-y|^{d+\alpha_1}},\end{align*} where we have used the facts that $|x'-y|>cR_1$ and $t<1$ in the second inequality.
On the other hand, when $|z|> {cR_1}/{4}$,
$$|\delta_{p^y}(t,x'-y;z)|\preceq p^y(t,x'-y\pm z)+p^y(t,x'-y).$$
Having this at hand and using \eqref{r1-1-2} and \eqref{p1-1-1-1-0}, we know that
$$\int_{\{|z|>{cR_1}/{4}\}} |\delta_{p^y}(t,x'-y;z)|\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(x;x')}}\,dz
\preceq \frac{\log(1+|x'-y|)}{|x'-y|^{d+\alpha_1}}.$$
Then, by \eqref{e:pp}, we find that
\begin{align*}
J_{22}&\preceq |x-x'|^{\beta_0}\cdot \int_{\{|z|>{cR_1}/{4}\}}|\delta_{p^y}(t,x'-y;z)|\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(x;x')}}\,dz  \preceq   |x-x'|^{\beta_0}\frac{\log(1+|x'-y|)}{|x'-y|^{d+\alpha_1}}.
\end{align*}
By the estimates for $J_{21}$ and $J_{22}$, we have
\begin{equation*}
J_2\preceq |x-x'|^{\beta_0}\log(1+|x'-y|)\rho^{y,0}_0(t,x'-y).
\end{equation*}

Putting the estimates of $J_1$ and $J_2$ together, we finally arrive at
\begin{align*}
|q_0(t,x,y)-q_0(t,x',y)|\preceq & |x-x'|\big( \rho_{-{1/\alpha(y)}}^{y,\beta_0}(t,x-y)+\rho_{-{1/\alpha(y)}}^{y,\beta_0}(t,x'-y)\big)\\
&+|x-x'|^{\beta_0}\log(1+|x'-y|)\rho^{y,0}_0(t,x'-y).
\end{align*}

{\bf Case (d): $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$ and $t^{{1/\alpha(y)}}\leqslant |x-y|< R_1$.}

We still define $J_1$ and $J_2$ by those in \eqref{p3-1-2aa}. Combining \eqref{p1-1-4} with \eqref{e:pp}, we arrive at
\begin{align*}
J_1 \preceq & t^{-{1/\alpha(y)}}|x-x'||x-y|^{\beta_0}\Bigg[\int_{\mathds R^d} \left[\left(t^{-{2}/{\alpha(y)}}|z|^2\right)\wedge 1\right]\\
&\qquad\qquad\qquad\times \big(
\rho_1^{y,0}(t,x-y)+\rho_1^{y,0}(t,x'-y)+\rho_1^{y,0}(t,x-y\pm z)+\rho_1^{y,0}(t,x'-y\pm z)\big)\\
&\qquad\qquad\qquad \times\bigg(\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\mathds 1_{\{|z|\leqslant 1\}}+\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(y;x)}}\mathds 1_{\{|z|> 1\}}\bigg)\,dz\Bigg].
\end{align*}
Noting that $t^{{1/\alpha(y)}}\leqslant |x-y|< R_1$ and using \eqref{l1-1-1}--\eqref{l1-1-3}, we obtain that
\begin{equation} \begin{split}
& \int_{\mathds R^d} \left[\left(t^{-{2}/{\alpha(y)}}|z|^2\right)\wedge 1\right]\big
(\rho_1^{y,0}(t,x-y\pm z)+\rho_1^{y,0}(t,x-y)\big)\\
&\qquad\qquad \times \bigg(\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\mathds 1_{\{|z|\leqslant 1\}}
+\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(y;x)}}\mathds 1_{\{|z|> 1\}}\bigg)\,dz\\
&\preceq \left(1+|\log t|\right)t^{-{(\overline{\alpha}(y;x)-\alpha(y))}/{\alpha(y)}}
\rho_0^{y,0}(t,x-y)\preceq \rho_{-\gamma}^{y,0}(t,x-y),
\end{split}
\end{equation}
where the last step is due to the fact that we can choose the constant $R_1$ small enough such that $$\frac{\overline{\alpha}(y;x)-\alpha(y)}{\alpha(y)}\leqslant
\frac{C|x-y|^{\beta_0}}{\alpha_1}<\gamma\quad \textrm{ for every }|x-y|\leqslant R_1.$$
Since $|x-x'|\leqslant C_0 t^{{1/\alpha(y)}}$ for some $C_0$ small enough,
$C_2t^{{1/\alpha(y)}}\leqslant |x'-y|\leqslant C_3R_1$ holds for some positive constants $C_2$ and $C_3$. Hence, \eqref{p3-1-4} still holds with $x$ replaced by $x'$.
Therefore, combining both the estimates above together, we arrive at
\begin{align*}
J_1 &\preceq |x-x'|\cdot |x-y|^{\beta_0}\cdot
\left(\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\right)\\
&\preceq |x-x'|\left(\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\right),
\end{align*}
where in the last step we have used the fact that
\begin{equation*}
|x'-y|\geqslant |x-y|-|x-x'| \geqslant |x-y|-C_0t^{{1/\alpha(y)}}\geqslant (1-C_0)|x-y|.
\end{equation*}

Now we are going to estimate $J_2$. \eqref{p1-1-2}
along with \eqref{e:pp} yields that
\begin{equation} \begin{split}
J_2 & \preceq |x-x'|^{\beta_0}\int_{\mathds R^d}\left[\left(t^{-{2}/{\alpha(y)}}|z|^2\right)\wedge 1\right]\cdot\Big(
\rho_1^{y,0}(t,x'\!-y)\!+\rho_1^{y,0}(t,x'\!-y\pm z)\Big)\\
&  \qquad\times \bigg(\frac{|\log|z||+1}{|z|^{d+\overline{\alpha}(x;x')}}\mathds 1_{\{|z|\leqslant 1\}}
\!+\frac{|\log|z||+1}{|z|^{d+\underline{\alpha}(x;x')}}\mathds 1_{\{|z|> 1\}}\!\!\bigg)\,dz.
\end{split}
\end{equation}
As noted above, it holds that $C_2t^{{1/\alpha(y)}}\leqslant |x'-y|\leqslant C_3R_1$. Although the indexes $\overline{\alpha}(y;x)$ and
$\underline{\alpha}(y;x)$ are replaced by $\overline{\alpha}(x;x')$ and $\underline{\alpha}(x;x')$ respectively, we can
still follow the proof of Lemma \ref{l1-1} to obtain
that
\begin{equation} \begin{split}
& \int_{\mathds R^d}\left[\left(t^{-{2}/{\alpha(y)}}|z|^2\right)\wedge 1\right]\cdot\big(
\rho_1^{y,0}(t,x'-y)+\rho_1^{y,0}(t,x'-y\pm z)\big)\\
&\qquad \qquad\qquad \qquad\qquad  \times  \bigg(\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(x;x')}}\mathds 1_{\{|z|\leqslant 1\}}
+\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(x;x')}}\mathds 1_{\{|z|> 1\}}\bigg)\,dz\\
& \preceq \left(1+|\log t|\right)t^{1-({\overline{\alpha}(x;x')}/{\alpha(y)})}\rho_0^{y,0}(t,x'-y).
\end{split}
\end{equation}
Note that when  $|x-y|\leqslant R_1$ and $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$,
\begin{align*}
|\overline{\alpha}(x;x')-\alpha(y)|&
\leqslant |\overline{\alpha}(x;x')-\alpha(x)|+|\alpha(x)-\alpha(y)|\leqslant C_4(t^{{\beta_0}/{\alpha(y)}}+R_1^{\beta_0}).
\end{align*}
So, by changing $R_1$ properly such that
$$t^{-{(\overline{\alpha}(x;x')-\alpha(y))}/{\alpha(y)}}\preceq \exp(C_5t|\log t|)\cdot t^{-C_4R_1^{\beta_0}}
\preceq t^{-\gamma/2}$$ and putting all these estimates into \eqref{p3-1-5a},  we arrive at
$$J_2 \preceq |x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y).$$
Therefore, according to the estimates for $J_1$ and $J_2$, we have
\begin{align*}
|q_0(t,x,y)-q_0(t,x',y)| \preceq & |x-x'|\left(\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\right) +|x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y).
\end{align*}

{\bf Case (e): $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$ and $|x-y|\leqslant t^{{1/\alpha(y)}}$.}

We still define $J_1$ and $J_2$ by those in \eqref{p3-1-2aa}. It is
easy to see that \eqref{p3-1-4} and \eqref{p3-1-5} still hold for
such case. Note that $|x'-y|\leqslant |x-y|+|x-x'|\leqslant
(1+C_0)t^{{1/\alpha(y)}}$. Using \eqref{p3-1-4} and
\eqref{p3-1-5}, and repeating the argument in {\bf Case (d)}, we
have
\begin{align*}
& J_1 \preceq |x-x'|\cdot |x-y|^{\beta_0}\cdot
\left(\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\right),\\
& J_2  \preceq |x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y).
\end{align*}
Then, we arrive at
\begin{align*}
&|q_0(t,x,y)-q_0(t,x',y)|\\
&\preceq|x-x'|\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+|x-x'||x-y|^{\beta_0}\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x'-y) +|x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y)\\
&\preceq|x-x'|\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+|x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y),
\end{align*}
where the last step follows from the property that
\begin{equation*}
|x-x'||x-y|^{\beta_0}=|x-x'|^{\beta_0}|x-x'|^{1-\beta_0}|x-y|^{\beta}\preceq t^{{1/\alpha(y)}}|x-x'|^{\beta_0}.
\end{equation*}

Combining all {\bf Cases (c)--(e)} together, we can find a constant $C_0>0$ small enough such that for every $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$
\begin{align*}
 |q_0(t,x,y)-q_0(t,x',y)|
 &\preceq |x-x'|\big(
\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)
+\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\big)\\
&\,\,+|x-x'|^{\beta_0}\big(1+\log(1+|x'-y|)\mathds 1_{\{|x'-y|>R_0\}}\big)\rho^{y,0}_{-\gamma}(t,x'-y).
\end{align*}

Furthermore, for $0<\gamma<\theta<{\beta_0}/{\alpha_2}$, we have
\begin{align*}
|x-x'|^{\beta_0}\rho^{y,0}_{-\gamma}(t,x'-y)&=
|x-x'|^{\beta_0-\alpha(y)\theta}|x-x'|^{\alpha(y)\theta}
\rho^{y,0}_{-\gamma}(t,x'-y)\\
& \preceq |x-x'|^{\beta_0-\alpha(y)\theta}\rho^{y,0}_{\theta-\gamma}(t,x'\!-y) \! \preceq |x-x'|^{\beta_0-\alpha_2\theta}\rho^{y,0}_{\theta-\gamma}(t,x'\!-y),
\end{align*}
where the second step above follows from $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$.
On the other hand, it holds that
\begin{align*}
 |x-x'|\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)
&=
|x-x'|^{\alpha_1(\beta_0-\alpha(x')\theta)/{\alpha(x')}}|x-x'|^{1-(\alpha_1(\beta_0-\alpha(x')\theta)/{\alpha(x')})}
\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\\
& \preceq |x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x')}}
t^{{(1/\alpha(y))}-({\alpha_1(\beta_0-\alpha(x')\theta)}/({\alpha(x')\alpha(y)}))}
\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\\
&\preceq|x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}
\rho^{y,\beta_0}_{-\gamma-(({\alpha_1}/{\alpha(y)})(({\beta_0}/{\alpha(x')})-\theta))}(t,x'-y)\\
&\preceq |x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}
\rho^{y,\beta_0}_{-\gamma+\theta-({\beta_0}/{\alpha(x')})}(t,x'-y),
\end{align*}
where in the first inequality we have used again that $|x-x'|\leqslant
C_0t^{{1/\alpha(y)}}$, and the second inequality follows from
\eqref{p3-1-3}. Similarly, it holds that
$$|x-x'|\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y) \preceq |x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}
\rho^{y,\beta_0}_{-\gamma+\theta-({\beta_0}/{\alpha(x)})}(t,x-y).$$
Hence, we arrive at that for every $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$ and $\varepsilon>0$
\begin{equation} \begin{split}
& |q_0(t,x,y)-q_0(t,x',y)| \\
& \preceq |x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}
\Big(
\rho^{y,\beta_0}_{-\gamma+\theta-({\beta_0}/{\alpha(x)})}(t,x-y)
+\rho^{y,\beta_0}_{-\gamma+\theta-({\beta_0}/{\alpha(x')})}(t,x'-y)\\
&\qquad   +\rho^{y,0}_{\theta-\gamma}(t,x'-y)+|x'-y|^{\varepsilon}\mathds 1_{\{|x'-y|>R_0\}}\rho^{y,0}_{\theta-\gamma}(t,x'-y)\Big).
\end{split}
\end{equation}

Therefore, according to all the five different cases above, \eqref{p3-1-1a-1} holds for $q_0(t,x,y)$.

\medskip

{\bf Case (a): $|x-x'|>R_1$.}

By \eqref{l2-1-2} and the condition $\beta_0>\alpha_2\theta$, it holds that
\begin{align*} |q_0(t,x,y)-q_0(t,x',y)|
&\leqslant |q_0(t,x,y)|+|q_0(t,x',y)|\preceq \rho_{-\gamma}^{y,\beta_0}(t,x-y)+\rho_{-\gamma}^{y,\beta_0}(t,x'-y)\\
&\preceq \big(|x-x'|^{{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}}\wedge1\big)\big(\rho_{-\gamma}^{y,\beta_0}(t,x-y)+\rho_{-\gamma}^{y,\beta_0}(t,x'-y)\big).\end{align*}

{\bf Case (d): $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$ and $t^{{1/\alpha(y)}}\leqslant |x-y|< R_1$.}

We still define $J_1$ and $J_2$ by those in \eqref{p3-1-2aa}. Combining \eqref{p1-1-4} with \eqref{e:pp}, we arrive at
\begin{align*}
J_1 \preceq & t^{-{1/\alpha(y)}}|x-x'||x-y|^{\beta_0}\Bigg[\int_{\mathds R^d} \left[\left(t^{-{2}/{\alpha(y)}}|z|^2\right)\wedge 1\right]\\
&\qquad\qquad\qquad\times \big(
\rho_1^{y,0}(t,x-y)+\rho_1^{y,0}(t,x'-y)+\rho_1^{y,0}(t,x-y\pm z)+\rho_1^{y,0}(t,x'-y\pm z)\big)\\
&\qquad\qquad\qquad \times\bigg(\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\mathds 1_{\{|z|\leqslant 1\}}+\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(y;x)}}\mathds 1_{\{|z|> 1\}}\bigg)\,dz\Bigg].
\end{align*}
Noting that $t^{{1/\alpha(y)}}\leqslant |x-y|< R_1$ and using \eqref{l1-1-1}--\eqref{l1-1-3}, we obtain that
\begin{equation} \begin{split}
& \int_{\mathds R^d} \left[\left(t^{-{2}/{\alpha(y)}}|z|^2\right)\wedge 1\right]\big
(\rho_1^{y,0}(t,x-y\pm z)+\rho_1^{y,0}(t,x-y)\big)\\
&\qquad\qquad \times \bigg(\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(y;x)}}\mathds 1_{\{|z|\leqslant 1\}}
+\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(y;x)}}\mathds 1_{\{|z|> 1\}}\bigg)\,dz\\
&\preceq \left(1+|\log t|\right)t^{-{(\overline{\alpha}(y;x)-\alpha(y))}/{\alpha(y)}}
\rho_0^{y,0}(t,x-y)\preceq \rho_{-\gamma}^{y,0}(t,x-y),
\end{split}
\end{equation}
where the last step is due to the fact that we can choose the constant $R_1$ small enough such that $$\frac{\overline{\alpha}(y;x)-\alpha(y)}{\alpha(y)}\leqslant
\frac{C|x-y|^{\beta_0}}{\alpha_1}<\gamma\quad \textrm{ for every }|x-y|\leqslant R_1.$$
Since $|x-x'|\leqslant C_0 t^{{1/\alpha(y)}}$ for some $C_0$ small enough,
$C_2t^{{1/\alpha(y)}}\leqslant |x'-y|\leqslant C_3R_1$ holds for some positive constants $C_2$ and $C_3$. Hence, \eqref{p3-1-4} still holds with $x$ replaced by $x'$.
Therefore, combining both the estimates above together, we arrive at
\begin{align*}
J_1 &\preceq |x-x'|\cdot |x-y|^{\beta_0}\cdot
\left(\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\right)\\
&\preceq |x-x'|\left(\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\right),
\end{align*}
where in the last step we have used the fact that
\begin{equation*}
|x'-y|\geqslant |x-y|-|x-x'| \geqslant |x-y|-C_0t^{{1/\alpha(y)}}\geqslant (1-C_0)|x-y|.
\end{equation*}

Now we are going to estimate $J_2$. \eqref{p1-1-2}
along with \eqref{e:pp} yields that
\begin{equation} \begin{split}
J_2 & \preceq |x-x'|^{\beta_0}\int_{\mathds R^d}\left[\left(t^{-{2}/{\alpha(y)}}|z|^2\right)\wedge 1\right]\cdot\Big(
\rho_1^{y,0}(t,x'\!-y)\!+\rho_1^{y,0}(t,x'\!-y\pm z)\Big)\\
&  \qquad\times \bigg(\frac{|\log|z||+1}{|z|^{d+\overline{\alpha}(x;x')}}\mathds 1_{\{|z|\leqslant 1\}}
\!+\frac{|\log|z||+1}{|z|^{d+\underline{\alpha}(x;x')}}\mathds 1_{\{|z|> 1\}}\!\!\bigg)\,dz.
\end{split}
\end{equation}
As noted above, it holds that $C_2t^{{1/\alpha(y)}}\leqslant |x'-y|\leqslant C_3R_1$. Although the indexes $\overline{\alpha}(y;x)$ and
$\underline{\alpha}(y;x)$ are replaced by $\overline{\alpha}(x;x')$ and $\underline{\alpha}(x;x')$ respectively, we can
still follow the proof of Lemma \ref{l1-1} to obtain
that
\begin{equation} \begin{split}
& \int_{\mathds R^d}\left[\left(t^{-{2}/{\alpha(y)}}|z|^2\right)\wedge 1\right]\cdot\big(
\rho_1^{y,0}(t,x'-y)+\rho_1^{y,0}(t,x'-y\pm z)\big)\\
&\qquad \qquad\qquad \qquad\qquad  \times  \bigg(\frac{1+|\log|z||}{|z|^{d+\overline{\alpha}(x;x')}}\mathds 1_{\{|z|\leqslant 1\}}
+\frac{1+|\log|z||}{|z|^{d+\underline{\alpha}(x;x')}}\mathds 1_{\{|z|> 1\}}\bigg)\,dz\\
& \preceq \left(1+|\log t|\right)t^{1-({\overline{\alpha}(x;x')}/{\alpha(y)})}\rho_0^{y,0}(t,x'-y).
\end{split}
\end{equation}
Note that when  $|x-y|\leqslant R_1$ and $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$,
\begin{align*}
|\overline{\alpha}(x;x')-\alpha(y)|&
\leqslant |\overline{\alpha}(x;x')-\alpha(x)|+|\alpha(x)-\alpha(y)|\leqslant C_4(t^{{\beta_0}/{\alpha(y)}}+R_1^{\beta_0}).
\end{align*}
So, by changing $R_1$ properly such that
$$t^{-{(\overline{\alpha}(x;x')-\alpha(y))}/{\alpha(y)}}\preceq \exp(C_5t|\log t|)\cdot t^{-C_4R_1^{\beta_0}}
\preceq t^{-\gamma/2}$$ and putting all these estimates into \eqref{p3-1-5a},  we arrive at
$$J_2 \preceq |x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y).$$
Therefore, according to the estimates for $J_1$ and $J_2$, we have
\begin{align*}
|q_0(t,x,y)-q_0(t,x',y)| \preceq & |x-x'|\left(\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\right) +|x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y).
\end{align*}

{\bf Case (e): $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$ and $|x-y|\leqslant t^{{1/\alpha(y)}}$.}

We still define $J_1$ and $J_2$ by those in \eqref{p3-1-2aa}. It is
easy to see that \eqref{p3-1-4} and \eqref{p3-1-5} still hold for
such case. Note that $|x'-y|\leqslant |x-y|+|x-x'|\leqslant
(1+C_0)t^{{1/\alpha(y)}}$. Using \eqref{p3-1-4} and
\eqref{p3-1-5}, and repeating the argument in {\bf Case (d)}, we
have
\begin{align*}
& J_1 \preceq |x-x'|\cdot |x-y|^{\beta_0}\cdot
\left(\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\right),\\
& J_2  \preceq |x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y).
\end{align*}
Then, we arrive at
\begin{align*}
&|q_0(t,x,y)-q_0(t,x',y)|\\
&\preceq|x-x'|\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+|x-x'||x-y|^{\beta_0}\rho^{y,0}_{-\gamma-({1/\alpha(y)})}(t,x'-y) +|x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y)\\
&\preceq|x-x'|\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)+|x-x'|^{\beta_0}\rho_{-\gamma}^{y,0}(t,x'-y),
\end{align*}
where the last step follows from the property that
\begin{equation*}
|x-x'||x-y|^{\beta_0}=|x-x'|^{\beta_0}|x-x'|^{1-\beta_0}|x-y|^{\beta}\preceq t^{{1/\alpha(y)}}|x-x'|^{\beta_0}.
\end{equation*}

Combining all {\bf Cases (c)--(e)} together, we can find a constant $C_0>0$ small enough such that for every $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$
\begin{align*}
 |q_0(t,x,y)-q_0(t,x',y)|
 &\preceq |x-x'|\big(
\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y)
+\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\big)\\
&\,\,+|x-x'|^{\beta_0}\big(1+\log(1+|x'-y|)\mathds 1_{\{|x'-y|>R_0\}}\big)\rho^{y,0}_{-\gamma}(t,x'-y).
\end{align*}

Furthermore, for $0<\gamma<\theta<{\beta_0}/{\alpha_2}$, we have
\begin{align*}
|x-x'|^{\beta_0}\rho^{y,0}_{-\gamma}(t,x'-y)&=
|x-x'|^{\beta_0-\alpha(y)\theta}|x-x'|^{\alpha(y)\theta}
\rho^{y,0}_{-\gamma}(t,x'-y)\\
& \preceq |x-x'|^{\beta_0-\alpha(y)\theta}\rho^{y,0}_{\theta-\gamma}(t,x'\!-y) \! \preceq |x-x'|^{\beta_0-\alpha_2\theta}\rho^{y,0}_{\theta-\gamma}(t,x'\!-y),
\end{align*}
where the second step above follows from $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$.
On the other hand, it holds that
\begin{align*}
 |x-x'|\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)
&=
|x-x'|^{\alpha_1(\beta_0-\alpha(x')\theta)/{\alpha(x')}}|x-x'|^{1-(\alpha_1(\beta_0-\alpha(x')\theta)/{\alpha(x')})}
\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\\
& \preceq |x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x')}}
t^{{(1/\alpha(y))}-({\alpha_1(\beta_0-\alpha(x')\theta)}/({\alpha(x')\alpha(y)}))}
\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x'-y)\\
&\preceq|x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}
\rho^{y,\beta_0}_{-\gamma-(({\alpha_1}/{\alpha(y)})(({\beta_0}/{\alpha(x')})-\theta))}(t,x'-y)\\
&\preceq |x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}
\rho^{y,\beta_0}_{-\gamma+\theta-({\beta_0}/{\alpha(x')})}(t,x'-y),
\end{align*}
where in the first inequality we have used again that $|x-x'|\leqslant
C_0t^{{1/\alpha(y)}}$, and the second inequality follows from
\eqref{p3-1-3}. Similarly, it holds that
$$|x-x'|\rho^{y,\beta_0}_{-\gamma-({1/\alpha(y)})}(t,x-y) \preceq |x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}
\rho^{y,\beta_0}_{-\gamma+\theta-({\beta_0}/{\alpha(x)})}(t,x-y).$$
Hence, we arrive at that for every $|x-x'|\leqslant C_0t^{{1/\alpha(y)}}$ and $\varepsilon>0$
\begin{equation} \begin{split}
& |q_0(t,x,y)-q_0(t,x',y)| \\
& \preceq |x-x'|^{\alpha_1(\beta_0-\alpha_2\theta)/{\alpha(x)}}
\Big(
\rho^{y,\beta_0}_{-\gamma+\theta-({\beta_0}/{\alpha(x)})}(t,x-y)
+\rho^{y,\beta_0}_{-\gamma+\theta-({\beta_0}/{\alpha(x')})}(t,x'-y)\\
&\qquad   +\rho^{y,0}_{\theta-\gamma}(t,x'-y)+|x'-y|^{\varepsilon}\mathds 1_{\{|x'-y|>R_0\}}\rho^{y,0}_{\theta-\gamma}(t,x'-y)\Big).
\end{split}
\end{equation}

Therefore, according to all the five different cases above, \eqref{p3-1-1a-1} holds for $q_0(t,x,y)$.

\medskip

(1) The proof is split into three cases.


{\bf Case (a): $|x-y|>2.$}

It holds that
\begin{equation} \begin{split}
 \int_{\mathds R^d} \rho_{\theta_1}^{z,\beta_1}(t-s,x-z)\rho_{\theta_2}^{y,\beta_2}(s,z-y)\,dz
&\leqslant  \int_{\{|z-y|\geqslant {|x-y|}/{2}\}} \rho_{\theta_1}^{z,\beta_1}(t-s,x-z)\rho_{\theta_2}^{y,\beta_2}(s,z-y)\,dz\\
 &\quad+\int_{\{|z-y|\leqslant {|x-y|}/{2}\}} \rho_{\theta_1}^{z,\beta_1}(t-s,x-z)\rho_{\theta_2}^{y,\beta_2}(s,z-y)\, dz\\
&=:J_1+J_2.
\end{split}
\end{equation}

If $|z-y|\geqslant {|x-y|}/{2}\geqslant 1\geqslant s^{{1/\alpha(y)}}$, then
\begin{equation} \begin{split}
\rho_0^{y,0}(s,z-y)&\preceq \frac{1}{|z-y|^{d+\alpha_1}}\preceq
\frac{1}{|x-y|^{d+\alpha_1}}\preceq \rho_0^{y,0}(t,x-y).
\end{split}
\end{equation}
Observe that
(see e.g.\ the proof of \cite[Lemma 2.2]{CZ}) for any $x,y, z\in
\mathds R^d$,
\begin{equation} \begin{split}
\big(|x-z|^{\beta_1}\wedge 1\big)
\big(|z-y|^{\beta_2}\wedge 1\big)\leqslant &\big(|x-z|^{\beta_1+\beta_2}\wedge 1\big) +\big(|x-z|^{\beta_1}\wedge 1\big)
\big(|x-y|^{\beta_2}\wedge 1\big).
\end{split}
\end{equation}
Combining this with \eqref{l3-2-2} and the first inequality in \eqref{l3-1-1},
we get that for $\beta_1,\beta_2\in (0,1)$,
 \begin{equation} \begin{split}
J_1&\preceq (t-s)^{\theta_1}s^{\theta_2}\rho_0^{y,0}(t,x-y)\int_{\mathds R^d}\rho^{z,\beta_1+\beta_2}_0(t-s,x-z)\,dz\\
&\quad +(t-s)^{\theta_1}s^{\theta_2}\rho_0^{y,\beta_2}(t,x-y)\int_{\mathds R^d}\rho^{z,\beta_1}_0(t-s,x-z)\,dz\\
&\preceq (t-s)^{\theta_1+[(({\beta_1+\beta_2})/{\alpha(x)
})\wedge 1]-1}s^{\theta_2}\big(1\!+\!|\log (t-s)|\mathds 1_{\{\beta_1+\beta_2=\alpha(x)\}}\big)\rho_0^{y,0}(t,x-y)\\
&\quad+
(t-s)^{[\theta_1+({\beta_1}/{\alpha(x)})\wedge 1]-1}s^{\theta_2}\big(1+|\log (t-s)|\mathds 1_{\{\beta_1=\alpha(x)\}}\big)\rho_0^{y,\beta_2}(t,x-y).
\end{split}
\end{equation}


If $|z-y|\leqslant {|x-y|}/{2}$, then $|x-z|\geqslant
{|x-y|}/{2}\geqslant 1 \geqslant (t-s)^{{1}/{\alpha(z)}}$, and so
\begin{align*}
& \rho_0^{z,0}(t-s,x-z)\preceq \frac{1}{|x-z|^{d+\alpha_1}}\preceq \frac{1}{|x-y|^{d+\alpha_1}}\preceq \rho_0^{y,0}(t,x-y).
\end{align*}
Combining this with
\begin{equation} \begin{split}
\big(|x-z|^{\beta_1}\wedge 1\big)
\big(|z-y|^{\beta_2}\wedge 1\big)\leqslant &\big(|z-y|^{\beta_1+\beta_2}\wedge 1\big) +\big(|z-y|^{\beta_2}\wedge 1\big)
\big(|x-y|^{\beta_1}\wedge 1\big),
\end{split}
\end{equation}
we arrive at
\begin{equation} \begin{split}
J_2&\preceq (t-s)^{\theta_1}s^{\theta_2}\rho_0^{y,0}(t,x-y)\int_{\mathds R^d}\rho^{y,\beta_1+\beta_2}_0(s,z-y)\, dz\\
&\quad +(t-s)^{\theta_1}s^{\theta_2}\rho_0^{y,\beta_1}(t,x-y)\int_{\mathds R^d}\rho^{y,\beta_2}_0(s,z-y)\, dz\\
&\preceq (t-s)^{\theta_1}s^{\theta_2+[(({\beta_1+\beta_2})/{\alpha(y)})\wedge 1]-1}
\big(1+|\log s|\mathds 1_{\{\beta_1+\beta_2=\alpha(y)\}}\big)\rho_0^{y,0}(t,x-y)\\
&\quad+
(t-s)^{\theta_1}s^{\theta_2+[({\beta_2}/{\alpha(y)})\wedge 1]-1}\big(1+|\log s|\mathds 1_{\{\beta_2=\alpha(y)\}}\big)\rho_0^{y,\beta_1}(t,x-y),
\end{split}
\end{equation}
where the second inequality follows from the first inequality in \eqref{l3-1-1-00}.


According to the above estimates for $J_1$ and $J_2$, \eqref{l3-2-1} holds in this case.



{\bf Case (b): $2t^{{1}/{\overline{\alpha}(y;t^{{1/\alpha_2}})}}\leqslant |x-y|\leqslant 2$.}

Let $J_1$ and $J_2$ be defined by \eqref{l3-2-1a}. If $|z-y|\geqslant
{|x-y|}/{2}$ and $0<s<t<1$, then $|z-y|\geqslant {|x-y|}/{2}$,
and so
\begin{equation} \begin{split}
\rho_0^{y,0}(s,z-y)&\preceq
\begin{cases}
|z-y|^{-d-\alpha(y)},& |z-y|\leqslant 1,\\
 |z-y|^{-d-\alpha_1},& |z-y|>1
\end{cases}
\\
&\preceq \begin{cases}
|x-y|^{-d-\alpha(y)},&|z-y|\leqslant 1,\\
|x-y|^{-d-\alpha_1},& |z-y|>1
\end{cases}
\\
&\preceq |x-y|^{-d-\alpha(y)}\preceq \rho^{y,0}_0(t,x-y),
\end{split}
\end{equation}
where in
the third inequality we have used the fact that
$$|x-y|^{-d-\alpha_1}\preceq |x-y|^{-d-\alpha(y)}\quad \textrm{ for all }|x-y|\leqslant 2 ,$$ and the last
inequality follows from
$$|x-y|^{-d-\alpha(y)} \preceq  \rho^{y,0}_0(t,x-y)\quad\textrm{ for all } |x-y|\geqslant 2t^{{1}/{\overline{\alpha}(y;t^{{1/\alpha_2}})}}\geqslant 2t^{{1/\alpha(y)}}.$$
Using \eqref{l3-2-6} and following the same argument of \eqref{l3-2-4}, we know that \eqref{l3-2-4} is satisfied too.


If $|z-y|<{|x-y|}/{2}$, then $|x-z|\geqslant {|x-y|}/{2}$,
and so we obtain
\begin{equation} \begin{split}
\rho_0^{z,0}(t-s,x-z)&\preceq
\begin{cases}
|x-z|^{-d-\alpha(z)},& |x-z|\leqslant 1,\\
|x-z|^{-d-\alpha_1}, & |x-z|>1
\end{cases}
\\
&\preceq |x-y|^{-d-\alpha(z)} \preceq |x-y|^{\alpha(y)-\alpha(z)}\cdot|x-y|^{-d-\alpha(y)}\\
&\preceq |x-y|^{-|\alpha(y)-\alpha(z)|}\cdot|x-y|^{-d-\alpha(y)}\\
&\preceq |x-y|^{-C|x-y|^{\beta_0}}\cdot|x-y|^{-d-\alpha(y)}\\
&\preceq \exp\big(C|\log|x-y||\cdot|x-y|^{\beta_0}\big)\cdot|x-y|^{-d-\alpha(y)}\\
&\preceq |x-y|^{-d-\alpha(y)}\preceq \rho_0^{y,0}(t,x-y),
\end{split}
\end{equation}
where in the second inequality we used the fact that if $|x-z|\geqslant {|x-y|}/{2}$ and $|x-y|\leqslant 2$, then
$|x-z|^{-d-\alpha_1}\preceq |x-y|^{-d-\alpha_1}\preceq |x-y|^{-d-\alpha(z)},$
the fifth inequality follows from the fact that
$$|\alpha(y)-\alpha(z)|\preceq |z-y|^{\beta_0}\leqslant C |x-y|^{\beta_0}\quad\textrm{ for all }|z-y|\leqslant {|x-y|}/{2},$$
in the seventh inequality we used $$\sup_{z\in \mathds R^d: |z|\leqslant 2}\exp\big(C|\log
|z||\cdot|z|^{\beta_0}\big)<\infty,$$ and the last inequality is due to
the same argument of the last one in \eqref{l3-2-6}.


Using the above inequality for $\rho_0^{z,0}(t-s,x-z)$ and following the same procedure of \eqref{l3-2-5a},
we know that \eqref{l3-2-5a} still holds.

Therefore, according to the estimates for $J_1$ and $J_2$, \eqref{l3-2-1} also holds in this case.



{\bf Case (c): $|x-y|\leqslant
2t^{{1}/{\overline{\alpha}(y;t^{{1/\alpha_2}})}}$.}


Note that for any $t \in (0,1]$ and $y \in \mathds R^d$,
\begin{equation} \begin{split}
1\leqslant&
\frac{t^{{1}/{\overline{\alpha}(y;t^{{1/\alpha_2}})}}}{t^{{1/\alpha(y)}}}\leqslant
t^{-\frac{\overline{\alpha}(y;t^{{1/\alpha_2}})-\alpha(y)}{\alpha(y)\overline{\alpha}(y;t^{{1/\alpha_2}})}}
\leqslant
t^{-\frac{Ct^{{\beta_0}/{\alpha_2}}}{\alpha_1^2}}\leqslant \exp\big(C|\log
t|\cdot t^{{\beta_0}/{\alpha_2}} \big)\leqslant C_1 ,
\end{split}
\end{equation}
hence $|x-y|\leqslant 2t^{{1}/{\overline{\alpha}(y;t^{{1/\alpha_2}})}}$
implies that $|x-y|\leqslant C_2 t^{{1/\alpha(y)}}$ for some constant
$C_2>0$.

On the other hand,
\begin{align*}
 \int_{\mathds R^d}\rho_{\theta_1}^{z,\beta_1}(t-s,x-z)\rho_{\theta_2}^{y,\beta_2}(s,z-y)\,dz
&\leqslant \int_{\{|z-y|> t^{{1/\alpha(y)}}\}}\rho_{\theta_1}^{z,\beta_1}(t-s,x-z)\rho_{\theta_2}^{y,\beta_2}(s,z-y)\,dz\\
&\quad+\int_{\{|z-y|\leqslant t^{{1/\alpha(y)}}\}}\rho_{\theta_1}^{z,\beta_1}(t-s,x-z)\rho_{\theta_2}^{y,\beta_2}(s,z-y)\, dz\\
&=:J_1+J_2.
\end{align*}

If $|z-y|\geqslant t^{{1/\alpha(y)}}>s^{{1/\alpha(y)}}$, then
\begin{align*}
\rho_0^{y,0}(s,z-y)\preceq |z-y|^{-d-\alpha(y)}\preceq t^{-({d+\alpha(y)})/{\alpha(y)}}\preceq \rho_0^{y,0}(t,x-y),
\end{align*}
where the second inequality follows from $|z-y|\geqslant t^{{1/\alpha(y)}}$, and the last inequality
is due to $t^{-({d+\alpha(y)})/{\alpha(y)}}\preceq \rho_0^{y,0}(t,x-y)$ for all $|x-y|\leqslant C_2t^{{1/\alpha(y)}}$. Applying the above estimate for $\rho_0^{y,0}(s,z-y)$ and following the same argument of \eqref{l3-2-4}, we can find that \eqref{l3-2-4} still holds
for $J_1$ here.



Now we turn to estimate for $J_2$, which is divided into the following two subcases:

{\bf Subcase (c1): $s>{t}/{2}$.}

If $|z-y|\leqslant t^{{1/\alpha(y)}}$, then
\begin{align*}
\rho_0^{y,0}(s,z-y)&\preceq s^{-({d/\alpha(y)})-1}\preceq t^{-({d/\alpha(y)})-1}\preceq \rho_0^{y,0}(t,x-y),
\end{align*}
where the second inequality follows
from $s>{t}/{2}$, and in the last inequality we have used the fact that
$t^{-({d/\alpha(y)})-1}\preceq \rho_0^{y,0}(t,x-y)$ for all $|x-y|\leqslant C_2t^{{1/\alpha(y)}}$.

Having the above estimate for $\rho_0^{y,0}(s,z-y)$ at hand, we also can follow the same procedure of \eqref{l3-2-4} to get that \begin{align*}
J_2&\preceq (t-s)^{\theta_1+(({\beta_1+\beta_2})/{\alpha(x)})-1}s^{\theta_2}\rho_0^{y,0}(t,x-y)+
(t-s)^{\theta_1+({\beta_1}/{\alpha(x)})-1}s^{\theta_2}\rho_0^{y,\beta_2}(t,x-y).
\end{align*}


{\bf Subcase (c2): $s\leqslant {t}/{2}$.}

If $|z-y|\leqslant t^{{1/\alpha(y)}}$,
then we have
\begin{align*}
\rho_0^{z,0}(t-s,x-z)&\preceq (t-s)^{-({d}/{\alpha(z)})-1}\preceq t^{-({d}/{\alpha(z)})-1}\preceq t^{-|({d}/{\alpha(z)})-({d/\alpha(y)})|}\cdot t^{-({d/\alpha(y)})-1}\\
&\preceq t^{-Ct^{{\beta_0}/{\alpha_2}}}\cdot t^{-({d/\alpha(y)})-1}\preceq t^{-({d/\alpha(y)})-1}\preceq \rho_0^{y,0}(t,x-y),
\end{align*}
where the second inequality is due to $(t-s)\geqslant {t}/{2}$, in the
fourth inequality we used the fact that
$|\alpha(y)-\alpha(z)|\preceq |z-y|^{\beta_0}\preceq t^{{\beta_0}/{\alpha(y)}}\preceq
t^{{\beta_0}/{\alpha_2}},$ the fifth inequality follows from
$$\sup_{t \in (0,1]}t^{-Ct^{{\beta_0}/{\alpha_2}}}\preceq \sup_{t \in (0,1]}
\exp\big(C|\log t|t^{{\beta_0}/{\alpha_2}}\big)<\infty,$$ and the last
inequality is again due to the fact that $t^{-({d/\alpha(y)})-1}\preceq
\rho_0^{y,0}(t,x-y)$ for all $|x-y|\leqslant C_2t^{{1/\alpha(y)}}$.

Using the above estimate for $\rho_0^{z,0}(t-s,x-z)$ and following the same procedure of \eqref{l3-2-5a},  we
can also get \eqref{l3-2-5a}.

Combining both estimates for $J_1$ and $J_2$, we know \eqref{l3-2-1} holds for {\bf Case (c)}.
Therefore, the proof of \eqref{l3-2-0} is complete.

{\bf Case (a): $|x-y|>2.$}

It holds that
\begin{equation} \begin{split}
 \int_{\mathds R^d} \rho_{\theta_1}^{z,\beta_1}(t-s,x-z)\rho_{\theta_2}^{y,\beta_2}(s,z-y)\,dz
&\leqslant  \int_{\{|z-y|\geqslant {|x-y|}/{2}\}} \rho_{\theta_1}^{z,\beta_1}(t-s,x-z)\rho_{\theta_2}^{y,\beta_2}(s,z-y)\,dz\\
 &\quad+\int_{\{|z-y|\leqslant {|x-y|}/{2}\}} \rho_{\theta_1}^{z,\beta_1}(t-s,x-z)\rho_{\theta_2}^{y,\beta_2}(s,z-y)\, dz\\
&=:J_1+J_2.
\end{split}
\end{equation}

If $|z-y|\geqslant {|x-y|}/{2}\geqslant 1\geqslant s^{{1/\alpha(y)}}$, then
\begin{equation} \begin{split}
\rho_0^{y,0}(s,z-y)&\preceq \frac{1}{|z-y|^{d+\alpha_1}}\preceq
\frac{1}{|x-y|^{d+\alpha_1}}\preceq \rho_0^{y,0}(t,x-y).
\end{split}
\end{equation}
Observe that
(see e.g.\ the proof of \cite[Lemma 2.2]{CZ}) for any $x,y, z\in
\mathds R^d$,
\begin{equation} \begin{split}
\big(|x-z|^{\beta_1}\wedge 1\big)
\big(|z-y|^{\beta_2}\wedge 1\big)\leqslant &\big(|x-z|^{\beta_1+\beta_2}\wedge 1\big) +\big(|x-z|^{\beta_1}\wedge 1\big)
\big(|x-y|^{\beta_2}\wedge 1\big).
\end{split}
\end{equation}
Combining this with \eqref{l3-2-2} and the first inequality in \eqref{l3-1-1},
we get that for $\beta_1,\beta_2\in (0,1)$,
 \begin{equation} \begin{split}
J_1&\preceq (t-s)^{\theta_1}s^{\theta_2}\rho_0^{y,0}(t,x-y)\int_{\mathds R^d}\rho^{z,\beta_1+\beta_2}_0(t-s,x-z)\,dz\\
&\quad +(t-s)^{\theta_1}s^{\theta_2}\rho_0^{y,\beta_2}(t,x-y)\int_{\mathds R^d}\rho^{z,\beta_1}_0(t-s,x-z)\,dz\\
&\preceq (t-s)^{\theta_1+[(({\beta_1+\beta_2})/{\alpha(x)
})\wedge 1]-1}s^{\theta_2}\big(1\!+\!|\log (t-s)|\mathds 1_{\{\beta_1+\beta_2=\alpha(x)\}}\big)\rho_0^{y,0}(t,x-y)\\
&\quad+
(t-s)^{[\theta_1+({\beta_1}/{\alpha(x)})\wedge 1]-1}s^{\theta_2}\big(1+|\log (t-s)|\mathds 1_{\{\beta_1=\alpha(x)\}}\big)\rho_0^{y,\beta_2}(t,x-y).
\end{split}
\end{equation}


If $|z-y|\leqslant {|x-y|}/{2}$, then $|x-z|\geqslant
{|x-y|}/{2}\geqslant 1 \geqslant (t-s)^{{1}/{\alpha(z)}}$, and so
\begin{align*}
& \rho_0^{z,0}(t-s,x-z)\preceq \frac{1}{|x-z|^{d+\alpha_1}}\preceq \frac{1}{|x-y|^{d+\alpha_1}}\preceq \rho_0^{y,0}(t,x-y).
\end{align*}
Combining this with
\begin{equation} \begin{split}
\big(|x-z|^{\beta_1}\wedge 1\big)
\big(|z-y|^{\beta_2}\wedge 1\big)\leqslant &\big(|z-y|^{\beta_1+\beta_2}\wedge 1\big) +\big(|z-y|^{\beta_2}\wedge 1\big)
\big(|x-y|^{\beta_1}\wedge 1\big),
\end{split}
\end{equation}
we arrive at
\begin{equation} \begin{split}
J_2&\preceq (t-s)^{\theta_1}s^{\theta_2}\rho_0^{y,0}(t,x-y)\int_{\mathds R^d}\rho^{y,\beta_1+\beta_2}_0(s,z-y)\, dz\\
&\quad +(t-s)^{\theta_1}s^{\theta_2}\rho_0^{y,\beta_1}(t,x-y)\int_{\mathds R^d}\rho^{y,\beta_2}_0(s,z-y)\, dz\\
&\preceq (t-s)^{\theta_1}s^{\theta_2+[(({\beta_1+\beta_2})/{\alpha(y)})\wedge 1]-1}
\big(1+|\log s|\mathds 1_{\{\beta_1+\beta_2=\alpha(y)\}}\big)\rho_0^{y,0}(t,x-y)\\
&\quad+
(t-s)^{\theta_1}s^{\theta_2+[({\beta_2}/{\alpha(y)})\wedge 1]-1}\big(1+|\log s|\mathds 1_{\{\beta_2=\alpha(y)\}}\big)\rho_0^{y,\beta_1}(t,x-y),
\end{split}
\end{equation}
where the second inequality follows from the first inequality in \eqref{l3-1-1-00}.


According to the above estimates for $J_1$ and $J_2$, \eqref{l3-2-1} holds in this case.

{\bf Subcase (c1): $s>{t}/{2}$.}

If $|z-y|\leqslant t^{{1/\alpha(y)}}$, then
\begin{align*}
\rho_0^{y,0}(s,z-y)&\preceq s^{-({d/\alpha(y)})-1}\preceq t^{-({d/\alpha(y)})-1}\preceq \rho_0^{y,0}(t,x-y),
\end{align*}
where the second inequality follows
from $s>{t}/{2}$, and in the last inequality we have used the fact that
$t^{-({d/\alpha(y)})-1}\preceq \rho_0^{y,0}(t,x-y)$ for all $|x-y|\leqslant C_2t^{{1/\alpha(y)}}$.

Having the above estimate for $\rho_0^{y,0}(s,z-y)$ at hand, we also can follow the same procedure of \eqref{l3-2-4} to get that \begin{align*}
J_2&\preceq (t-s)^{\theta_1+(({\beta_1+\beta_2})/{\alpha(x)})-1}s^{\theta_2}\rho_0^{y,0}(t,x-y)+
(t-s)^{\theta_1+({\beta_1}/{\alpha(x)})-1}s^{\theta_2}\rho_0^{y,\beta_2}(t,x-y).
\end{align*}

For this, we first define $q_n(t,x,y)$ inductively by
\begin{equation} q_n(t,x,y):=\int_0^t\int_{\mathds R^d}q_0(t-s,x,z)q_{n-1}(s,z,y)\,dz\,ds,\ n\geqslant1,\ t\in(0,1].
\end{equation}

(ii) Suppose that there are some $y_0\in \mathds R^d$ and $r\in(0,\infty]$ such that $\alpha(z)=\alpha(y_0)$ for all $z\in B(y_0,r_0)$.
According to \eqref{l2-1-33a}, it is easy to verify that for every $z \in \mathds R^d$,
\begin{equation} \begin{split}
|q_0(s,z,y_0)|&\preceq \big(|z-y_0|^{\beta_0}\wedge 1\big)\cdot
\begin{cases}
\frac{1}{(s^{{1/\alpha(y_0)}}+|z-y_0|)^{d+\alpha(y_0)}},& |z-y_0|\leqslant r_0,\\
\frac{1}{|z-y_0|^{d+\alpha_1}},&|z-y_0|> r_0
\end{cases}\\
&\preceq \rho^{y_0,\beta_0}_0(s,z-y_0).
\end{split}
\end{equation}
This along with the fact that $|q_0(t-s,x,z)|\preceq \rho^{z,\beta_0}_{-\gamma}(t-s,x-z)$ for every $x,z\in \mathds R^d$ yields that for all $x\in \mathds R^d$,
\begin{align*}
|q_1(t,x,y_0)|&\preceq \int_0^t\int_{\mathds R^d}\rho^{z,\beta_0}_{-\gamma}(t-s,x-z)\rho^{y_0,\beta_0}_0(s,z-y_0)\,dz\,ds\\
&\leqslant C\mathscr{B}\big(({\widehat\beta_0}/{\alpha_2})-\gamma,({ \beta_0}/{\alpha_2})-\gamma\big)
\big(\rho^{y_0,0}_{({\widehat \beta_0}/{\alpha_2})+(({\widehat \beta_0}/{\alpha_2})-\gamma)}+\rho^{y_0,\beta_0}_{({\beta_0}/{\alpha_2})-\gamma}\big)(t,x-y_0).
\end{align*}
Following the same arguments in part (i), we find that for every $n \geqslant 0$,
\begin{align*} |q_n(t,x,y_0)|
&\leqslant \frac{\big[C \Gamma(({\beta_0}/{\alpha_2})-\gamma )\big]^{n+1}}{\Gamma\big((n+1)(({\widehat \beta_0}/{\alpha_2})-\gamma)\big)}
\Big(\rho_{({\widehat \beta_0}/{\alpha_2})+n(({\widehat\beta_0}/{\alpha_2})-\gamma)}^{y_0,0}+\rho_{n(({ \beta_0}/{\alpha_2})-\gamma)}^{y_0,\beta_0} \Big)(t,x-y_0),\end{align*}
which implies $q(t,x,y):=\sum_{n=1}^{\infty}q_n(t,x,y)$ is absolutely convergent and gives us \eqref{p3-1-2b} immediately.

(iv) Now we are going to prove the case that $\kappa(x,z)$ depends on $z$.
Due to the assumption $({\alpha_2}/{\alpha_1})-1<{\beta_0^{**}}/{\alpha_2}$, we can choose $\gamma>0$ small enough such that
$\gamma+({\alpha_2}/{\alpha_1})-1=:\gamma_2 <{\beta_0^{**}}/{\alpha_2}$. Using \eqref{l2-1-1} and following the same arguments in part (i) with $\gamma_2 $ instead of $\gamma$, we can obtain that for
every $n\geqslant 1$ and $(t,x,y)\in (0,1]\times \mathds R^d \times \mathds R^d$,
\begin{equation} \begin{split}
|q_n(t,x,y)|\leqslant &\frac{\big[C \Gamma(({\beta_0^{**}}/{\alpha_2})-\gamma_2  )\big]^{n+1}}{\Gamma\big((n+1)(({\beta_0^{**}}/{\alpha_2})-\gamma_2 )\big)} \bigg(\rho_{(n+1)(({\beta_0^{**}}/{\alpha_2})-\gamma_2 )}^{y,0}+\rho_{-\gamma_2 +n({\beta_0^{**}}/{\alpha_2}
-\gamma_2 )}^{y,\beta_0} \bigg)(t,x-y).
\end{split}
\end{equation}
Using this and \eqref{l2-1-1}, we find immediately that $\sum_{n=0}^{\infty}|q_n(t,x,y)|<\infty$ and so
\eqref{p3-1-2} is true.

Note that, according to Proposition \ref{p3-1-1a-p}(2), in this case \eqref{p3-1-8a} holds with
$\gamma_2$ in place of  $\gamma $. (Note that here $\beta_0$ is not replaced by $\beta_0^{**}$.) This along with \eqref{p3-1-2} and the same argument in (iii) gives us \eqref{p3-1-2a}.

According to \eqref{p3-1-6a}, we have
\begin{align*}
 \sum_{n=1}^{\infty}|q_n(t,x,y)|
& \leqslant
 \left(\sum_{n=1}^\infty \frac{\big[C \Gamma(({\beta_0}/{\alpha_2})-\gamma)\big]^{n+1}}{\Gamma\big((n+1)(({\beta_0}/{\alpha_2})-\gamma)\big)}
 \right)\Big(\rho_{3(({\beta_0}/{\alpha_2})-\gamma)}^{y,0}+\rho_{({\beta_0}/{\alpha_2})-2\gamma}^{y,\beta_0} \Big)(t,x-y) \preceq \rho^{y,0}_0(t,x-y),
\end{align*}
where in the last inequality we choose $\gamma>0$ small enough such that
$\gamma<{\beta_0}/({2\alpha_2})$.

(1) We first suppose that $\kappa(x,z)$ is independent of $z$.

{\bf Case (a): $|x-y|\leqslant t^{1/\alpha(x)}$.}


According to \eqref{p3-2-1}, we can easily see that \eqref{p3-3-1} holds.


{\bf Case (b): $|x-y|>2$.}

We have
\begin{equation} \begin{split}
 \left|\int_{\mathds R^d} p^z(t-s,x-z)q(s,z,y)\,dz\right|
&\leqslant \int_{\{|z-y|>{|x-y|}/{2}\}} p^z(t-s,x-z)|q(s,z,y)|\,dz\\
&\quad
+\int_{\{|z-y|\leqslant {|x-y|}/{2}\}} p^z(t-s,x-z)|q(s,z,y)|\,dz\\
&=:J_1+J_2.
\end{split}
\end{equation}When $|z-y|\geqslant {|x-y|}/{2}\geqslant 1$, it follows from \eqref{p3-1-2e} that for any $s\in (0,1]$ and $y,z\in \mathds R^d$,
\begin{equation*}
|q(s,z,y)|\preceq \frac{1}{|z-y|^{d+\alpha_1}}\preceq \frac{1}{|x-y|^{d+\alpha_1}}.
\end{equation*}
Therefore, by \eqref{p1-1-1-1-0} and \eqref{l3-1-1},
\begin{align*}
J_1&\preceq \frac{1}{|x-y|^{d+\alpha_1}}\int_{\mathds R^d}\rho^{z,0}_1(t-s,x-z)\, dz\preceq \frac{1}{|x-y|^{d+\alpha_1}}.
\end{align*}
Meanwhile, it is not difficult to see that condition $|z-y|\leqslant {|x-y|}/{2}$ implies
$|z-x|\geqslant {|x-y|}/{2}\geqslant 1$, and so
\begin{equation*}
p^z(t-s,x-z)\preceq \frac{t-s}{|x-z|^{d+\alpha_1}}\preceq \frac{t}{|x-z|^{d+\alpha_1}}.
\end{equation*}
This, along with \eqref{p3-1-1} and \eqref{l3-1-1-00}, yields that
\begin{align*}
J_2&\preceq \frac{t}{|x-y|^{d+\alpha_1}}\int_{\mathds R^d}\left(
\rho^{y,0}_{({\beta_0}/{\alpha_2})-\gamma}+\rho^{y, \beta_0}_{-\gamma}\right)(s,z-y)\, dz\preceq \frac{t}{|x-y|^{d+\alpha_1}}\cdot s^{-1+({\beta_0}/{\alpha_2})-\gamma}.
\end{align*}


Combining all the estimates above together and choosing $0<\gamma<{\beta_0}/{\alpha_2}$, we find that
\begin{align*}
 \left|\int_0^t \int_{\mathds R^d}p^z(t-s,x-z)q(s,z,y)\,dz\,ds\right|
&\preceq \int_0^t (J_1+J_2)\,ds\preceq \frac{t}{|x-y|^{d+\alpha_1}}\cdot \big(1+t^{({\beta_0}/{\alpha_2})-\gamma}\big)\!\preceq \frac{t}{|x-y|^{d+\alpha_1}}.
\end{align*}
Then, the desired assertion \eqref{p3-3-1}  immediately follows from the estimate above and \eqref{eq2-1}.

{\bf Case (c): $t^{{1}/ \alpha(x)}\leqslant |x-y|\leqslant 2$.}

We still define $J_1$ and $J_2$ by those in \eqref{p3-3-2}.
If $|z-y|\geqslant {|x-y|}/{2}$,
then, by  \eqref{p3-1-2e}, we have
\begin{align*}
|q(s,z,y)|&\preceq
\begin{cases}
s^{-d/\alpha(y)},& |z-y|\leqslant s^{1/\alpha(y)},\\
|z-y|^{-d-\alpha_2},& s^{{1}/{\alpha(y)}}\leqslant|z-y|\leqslant 1,\\
 |z-y|^{-d-\alpha_1},& |z-y|>1
\end{cases}
\\
&\preceq
\begin{cases}
|x-y|^{-d-\alpha(y)},& |z-y|\leqslant s^{{1}/{\alpha(y)}},\\
|x-y|^{-d-\alpha_2},& s^{{1}/{\alpha(y)}}\leqslant|z-y|\leqslant 1,\\
|x-y|^{-d-\alpha_1},& |z-y|>1
\end{cases}
\\
&\preceq |x-y|^{-d-\alpha_2},
\end{align*}
where in the second inequality we have used that fact that if
$|z-y|\leqslant s^{1/\alpha(y)}$ and $|x-y|\preceq |z-y|$, then
$$s^{-d/\alpha(y)}\preceq |z-y|^{-d-\alpha(y)}\preceq |x-y|^{-d-\alpha(y)},$$
the last inequality follows from the fact that $|x-y|^{-d-\alpha_1}\preceq |x-y|^{-d-\alpha_2}$, thanks to $|x-y|\leqslant 2$.
Hence,
\begin{align*}
J_1&\preceq \frac{1}{|x-y|^{d+\alpha_2}} \int_{\mathds R^d}\rho^{z,0}_1(t-s,x-z)\,dz \preceq \frac{1}{|x-y|^{d+\alpha_2}}.
\end{align*}
At the same time, if $|z-y|\leqslant {|x-y|}/{2}$, then
\begin{align*}
p^z(t-s,x-z)&\preceq \frac{t-s}{|x-z|^{d+\alpha(z)}}\preceq \frac{t}{|x-y|^{d+\alpha(z)}}\preceq \frac{t}{|x-y|^{d+\alpha_2}},
\end{align*}
where the last inequality follows from $|x-y|^{-d-\alpha(z)}\preceq |x-y|^{-d-\alpha_2}$ since $|x-y|\leqslant 2$.
Combining this estimate with \eqref{p3-1-1},  we arrive at
$$
J_2 \preceq \frac{t}{|x-y|^{d+\alpha_2}}\int_{\mathds R^d}\left(
\rho^{y,0}_{({\beta_0}/{\alpha_2})-\gamma}+\rho^{y,\beta_0}_{-\gamma}\right)(s,z-y)\,dz \preceq \frac{t}{|x-y|^{d+\alpha_2}}\cdot s^{-1+(\beta_0/{\alpha_2})-\gamma}.
$$

Using all the estimates above and choosing $0<\gamma<{\beta_0}/{\alpha_2}$, we get
\begin{align*}
 \left|\int_0^t \int_{\mathds R^d}p^z(t-s,x-z)q(s,z,y)\,dz\,ds\right|
&\preceq \int_0^t (J_1+J_2)\,ds\preceq \frac{t}{|x-y|^{d+\alpha_2}}\cdot \left(1+t^{({\beta_0}/{\alpha_2})-\gamma}\right)\!\preceq \frac{t}{|x-y|^{d+\alpha_2}}.
\end{align*}
This, along with \eqref{eq2-1} immediately yields \eqref{p3-3-1}.

{\bf Case (b): $|x-y|>2$.}

We have
\begin{equation} \begin{split}
 \left|\int_{\mathds R^d} p^z(t-s,x-z)q(s,z,y)\,dz\right|
&\leqslant \int_{\{|z-y|>{|x-y|}/{2}\}} p^z(t-s,x-z)|q(s,z,y)|\,dz\\
&\quad
+\int_{\{|z-y|\leqslant {|x-y|}/{2}\}} p^z(t-s,x-z)|q(s,z,y)|\,dz\\
&=:J_1+J_2.
\end{split}
\end{equation}When $|z-y|\geqslant {|x-y|}/{2}\geqslant 1$, it follows from \eqref{p3-1-2e} that for any $s\in (0,1]$ and $y,z\in \mathds R^d$,
\begin{equation*}
|q(s,z,y)|\preceq \frac{1}{|z-y|^{d+\alpha_1}}\preceq \frac{1}{|x-y|^{d+\alpha_1}}.
\end{equation*}
Therefore, by \eqref{p1-1-1-1-0} and \eqref{l3-1-1},
\begin{align*}
J_1&\preceq \frac{1}{|x-y|^{d+\alpha_1}}\int_{\mathds R^d}\rho^{z,0}_1(t-s,x-z)\, dz\preceq \frac{1}{|x-y|^{d+\alpha_1}}.
\end{align*}
Meanwhile, it is not difficult to see that condition $|z-y|\leqslant {|x-y|}/{2}$ implies
$|z-x|\geqslant {|x-y|}/{2}\geqslant 1$, and so
\begin{equation*}
p^z(t-s,x-z)\preceq \frac{t-s}{|x-z|^{d+\alpha_1}}\preceq \frac{t}{|x-z|^{d+\alpha_1}}.
\end{equation*}
This, along with \eqref{p3-1-1} and \eqref{l3-1-1-00}, yields that
\begin{align*}
J_2&\preceq \frac{t}{|x-y|^{d+\alpha_1}}\int_{\mathds R^d}\left(
\rho^{y,0}_{({\beta_0}/{\alpha_2})-\gamma}+\rho^{y, \beta_0}_{-\gamma}\right)(s,z-y)\, dz\preceq \frac{t}{|x-y|^{d+\alpha_1}}\cdot s^{-1+({\beta_0}/{\alpha_2})-\gamma}.
\end{align*}


Combining all the estimates above together and choosing $0<\gamma<{\beta_0}/{\alpha_2}$, we find that
\begin{align*}
 \left|\int_0^t \int_{\mathds R^d}p^z(t-s,x-z)q(s,z,y)\,dz\,ds\right|
&\preceq \int_0^t (J_1+J_2)\,ds\preceq \frac{t}{|x-y|^{d+\alpha_1}}\cdot \big(1+t^{({\beta_0}/{\alpha_2})-\gamma}\big)\!\preceq \frac{t}{|x-y|^{d+\alpha_1}}.
\end{align*}
Then, the desired assertion \eqref{p3-3-1}  immediately follows from the estimate above and \eqref{eq2-1}.

We first show that \eqref{l4-4-1} holds for $p^y_{{\kappa_1}/{2}}$. Indeed, for every $x,x'\in \mathds R^d$ such that $|x-x'|\leqslant 1$,
\begin{align*}
\big|\nabla p^y_{{\kappa_1}/{2}}(1,x)-\nabla p^y_{{\kappa_1}/{2}}(1,x')\big|&=
\left|\int_0^1 \frac{d}{d \theta}\left(\nabla p^y_{{\kappa_1}/{2}}
\left(1,x+\theta(x'-x)\right)\right)\,d\theta\right|\\
&\leqslant |x-x'|\cdot\int_0^1 \left|\nabla^2 p^y_{{\kappa_1}/{2}}
\left(1,x+\theta(x'-x)\right)\right|\,d\theta\\
&\preceq |x-x'|\cdot \int_0^1 \left(1+\left|x+\theta(x'-x)\right|\right)^{-d-\alpha(y)-2}\,d\theta\\
&\preceq |x-x'|\cdot \left(1+|x|\right)^{-d-\alpha(y)-2},
\end{align*}
where in the third inequality we have used \eqref{p1-1-1}, and the last inequality is due to
the fact that for all $\theta\in [0,1]$ and $x,x'\in \mathds R^d$ with $|x-x'|\leqslant 1$
\begin{equation*}
\left(1+\left|x+\theta(x'-x)\right|\right)^{-1}\preceq \left(1+|x|\right)^{-1}.
\end{equation*}

Combining both estimates above yields that for all $x,x'\in \mathds R^d$,
\begin{equation} \begin{split}
\big|\nabla p^y_{{\kappa_1}/{2}}(1,x)-\nabla p^y_{{\kappa_1}/{2}}(1,x')\big|
\preceq &\left(|x-x'|\wedge 1\right)\left(
(1+|x|)^{-d-\alpha(y)}+
(1+|x'|)^{-d-\alpha(y)}\right).
\end{split}
\end{equation}

(i) Note that for all $t\in (0,1]$ and $x,y,z \in \mathds R^d$,
\begin{equation} \begin{split}
 p^x(t,z)-p^y(t,z)
&=\int_0^t \frac{d}{ds}\bigg(\int_{\mathds R^d}p^x(s,w)p^y(t-s,z-w)\,dw\bigg)\,ds\\
&=\int_0^t \bigg(\int_{\mathds R^d}\big( {\mathcal L}^x p^x(s,w)\,p^y(t-s,z-w) -p^x(s,w)\, {\mathcal L}^y
p^y(t-s,z-w)\big)\,dw\bigg)\,ds\\
&=\int_0^{{t}/{2}}\int_{\mathds R^d}\big( {\mathcal L}^x- {\mathcal L}^y\big) p^x(s,w)\,p^y(t-s,z-w)\,dw\,ds\\
&\quad +\int_{{t}/{2}}^t\int_{\mathds R^d} p^x(s,w)\big( {\mathcal L}^x- {\mathcal L}^y\big)
p^y(t-s,z-w)\,dw\,ds\\
&=\int_0^{{t}/{2}}\bigg(\int_{\mathds R^d}\big( {\mathcal L}^x- {\mathcal L}^y\big) p^x(s,w)
\big(p^y(t-s,z-w)-p^y(t-s,z)\big)\,dw\bigg)\,ds\\
&\quad +\int_{{t}/{2}}^t\bigg(\int_{\mathds R^d} \big(p^x(s,w)-p^x(s,z)\big) \big( {\mathcal L}^x- {\mathcal L}^y\big)
p^y(t-s,z-w)\,dw\bigg)\,ds\\
&=:J_1+J_2.
\end{split}
\end{equation}
Here, the first equality is due to the following estimate which we will verify later
\begin{equation*}
\int_0^t \left|\frac{d}{ds}\bigg(\int_{\mathds R^d}p^x(s,w)p^y(t-s,z-w)\,dw\bigg)\,\right|ds<\infty.\end{equation*}
By estimates for $p^x(\cdot, \cdot)$ and $p^y(\cdot, \cdot)$ in Lemma \ref{p1-1},
we can change the order of derivatives and integrals in the second equality. The third and the fourth equalities above follow from the
following facts respectively
\begin{align*}
\int_{\mathds R^d}  {\mathcal L}^x f(z_1) g(z_1) \,dz_1=\int_{\mathds R^d} f(z_1)  {\mathcal L}^x g(z_1) \,dz_1,\quad f,g \in C_c^{\infty}(\mathds R^d),
\end{align*}
\begin{align*}
\int_{\mathds R^d}  {\mathcal L}^y f(z_1) g(z_1)\, dz_1=\int_{\mathds R^d} f(z_1)  {\mathcal L}^y g(z_1) \, dz_1, \quad f,g \in C_c^{\infty}(\mathds R^d)
\end{align*} and
\begin{align*}
\int_{\mathds R^d}  {\mathcal L}^x f(z_1)\,dz_1=\int_{\mathds R^d}  {\mathcal L}^y f(z_1)\,dz_1=0,\quad f \in C_c^{\infty}(\mathds R^d).
\end{align*}
Note that, also due to estimates for $p^x(\cdot, \cdot)$ and $p^y(\cdot, \cdot)$,  the equalities above are still true for $p^x(t,\cdot)$ and $p^y(t,\cdot)$.

By Lemma \ref{l1-2}, for any $\gamma>0$ there is a constant $R_0:=R_0(\alpha,\kappa,\gamma)\in(0,1)$ such that for all $t\in(0,1]$ and $x,y,w\in \mathds R^d$ with $|x-y|\leqslant R_0$,
\begin{equation} \big|\big( {\mathcal L}^x- {\mathcal L}^y\big)p^x(t,w)\big|\preceq (|x-y|^{\beta_0}\wedge 1)\cdot\tilde \rho^{x,0}_{-\gamma}(t,w).
\end{equation}
On the other hand, for any $\theta \in (0,1)$ and $\gamma\in (0,1)$, there exists a
constant $R_1:=R_1(\alpha,\kappa,\gamma)\in(0,R_0)$ such that for all
 $x,y,z\in\mathds R^d$ with $|x-y|\leqslant R_1$, $0<s\leqslant t\leqslant1$,
\begin{equation} \begin{split}
 \big|p^y(t-s,z-w)-p^y(t-s,z)\big|
&\preceq \big[\big((t-s)^{-{1/\alpha(y)}}|w|\big)\wedge 1\big]\cdot
\big[\rho^{y,0}_1(t-s,z-w)+\rho^{y,0}_1(t-s,z)\big]\\
&\preceq \big[\big((t-s)^{-{1/\alpha(y)}}|w|\big)^{\theta}\wedge 1\big]\cdot
\big[\rho^{y,0}_1(t-s,z-w)+\rho^{y,0}_1(t-s,z)\big]\\
&\preceq \big[\big((t-s)^{-{1}/{\alpha_1}}|w|\big)^{\theta}\wedge 1\big]\cdot
\big[\rho^{x,0}_{1-\gamma}(t-s,z-w)+\rho^{x,0}_{1-\gamma}(t-s,z)\big]\\
&\preceq \big(|w|^{\theta}\wedge 1\big)\cdot
\big[\rho^{x,0}_{1-\gamma-({\theta}/{\alpha_1})}(t-s,z-w)+\rho^{x,0}_{1-\gamma-({\theta}/{\alpha_1})}(t-s,z)\big],
\end{split}
\end{equation}
where the first inequality follows from \eqref{p1-1-3} and in the third inequality we have used \eqref{l4-1-5}.

Next, we choose $\theta\in(0,1\wedge \alpha_1)$ and $0<\gamma<({\theta}/{\alpha_2})\wedge ((1-({\theta}/{\alpha_1}))/2)$. Then, according to
\eqref{l4-1-4} and \eqref{l4-1-6}, for any $t\in(0,1]$ and $x,y,z\in \mathds R^d$ with $|x-y|\leqslant R_1$,
\begin{align*}
J_1&\preceq |x-y|^{\beta_0}\cdot\bigg(\int_0^{{t}/{2}}\int_{\mathds R^d}\tilde \rho^{x,\theta}_{-\gamma}(s,w)\tilde \rho^{x,0}_{1-\gamma-({\theta}/{\alpha_1})}(t-s,z-w)\,dw\,ds\\
&\qquad\qquad \qquad +\int_0^{{t}/{2}}\int_{\mathds R^d}\tilde \rho^{x,\theta}_{-\gamma}(s,w)
\tilde \rho^{x,0}_{1-\gamma-({\theta}/{\alpha_1})}(t-s,z)\,dw\,ds\bigg)\\
&=:|x-y|^{\beta_0}\cdot \big(J_{11}+J_{12}\big).
\end{align*}
As mentioned in Remark \ref{r3-3}(2), \eqref{r3-2-1} holds for $\tilde \rho$, from which we can obtain that
\begin{equation*}
J_{11}\preceq \tilde \rho^{x,0}_{1-2\gamma-({\theta}/{\alpha_1})}(t,z).
\end{equation*}
At the same time, observe that for every $0<s<{t}/{2}$,
\begin{equation*}
\tilde \rho^{x,0}_{1-\gamma-({\theta}/{\alpha_1})}(t-s,z)\preceq \tilde
\rho^{x,0}_{1-\gamma-({\theta}/{\alpha_1})}(t,z),
\end{equation*}
then we have
\begin{equation} \begin{split}
J_{12}&\preceq \tilde \rho^{x,0}_{1-\gamma-({\theta}/{\alpha_1})}(t,z)
\int_0^{{t}/{2}}\int_{\mathds R^d}\tilde \rho^{x,\theta}_{-\gamma}(s,w)\,dw\,ds \\
&\preceq \tilde \rho^{x,0}_{1-\gamma-({\theta}/{\alpha_1})}(t,z) \int_0^{{t}/{2}}s^{-1-\gamma+({\theta}/{\alpha_2})}\,ds \preceq \tilde \rho^{x,0}_{1-2\gamma-({\theta}/{\alpha_1})}(t,z),
\end{split}
\end{equation}
where in the second inequality we used the fact that \eqref{l3-1-1-00} is true for $\tilde \rho$, see again
Remark \ref{r3-3}(2).
By both estimates for $J_{11}$ and $J_{12}$, we get that for any $t\in(0,1]$ and $x,y,z\in \mathds R^d$ with $|x-y|\leqslant R_1$,
\begin{equation*}
J_1 \preceq |x-y|^{\beta_0}\cdot\tilde \rho^{x,0}_{1-2\gamma-({\theta}/{\alpha_1})}(t,z).
\end{equation*}
 For $J_2$, we need to handle the singularity near $s=t$. As the same way as before, we can obtain that for all $t\in (0,1]$ and
$x,y,z,w\in \mathds R^d$ with $|x-y|\leqslant R_1$,
\begin{align*}
\big|\big( {\mathcal L}^x- {\mathcal L}^y\big)p^y(t-s,z-w)\big|
&\preceq \big(|x-y|^{\beta_0}\wedge 1\big)\cdot\tilde \rho^{y,0}_{-\gamma}(t-s,z-w)\preceq \big(|x-y|^{\beta_0}\wedge 1\big)\cdot \tilde \rho^{x,0}_{-2\gamma}(t-s,z-w)\end{align*} and
\begin{align*}
\big|p^x(s,w)-p^x(s,z)\big|\preceq \big(|z-w|^{\theta}\wedge 1\big) \cdot\big(\rho^{x,0}_{1-({\theta}/{\alpha_1})}(s,z)+\rho^{x,0}_{1-({\theta}/{\alpha_1})}(s,w)\big).
\end{align*}
Using both estimates above and following the same argument as that for $J_1$, we can get that  for any $t\in(0,1]$ and $x,y,z\in \mathds R^d$ with $|x-y|\leqslant R_1$, $$J_2 \preceq
|x-y|^{\beta_0}\tilde \rho^{x,0}_{1-2\gamma-({\theta}/{\alpha_1})}(t,z).$$ Then, \eqref{l4-1-1} is proved.

On the one hand, \eqref{l4-1-1} yields that
\begin{align*}
J_1& \preceq \int_{\mathds R^d} \tilde \rho^{x,\beta_0}_{1-2\gamma-({\theta}/{\alpha_1})}(t,x-y)\,dy\preceq t^{(\beta_0/{\alpha_2})-2\gamma-({\theta}/{\alpha_1})},
\end{align*}
where the last inequality follows from the fact that \eqref{l3-1-1-00} holds for $\tilde \rho$.

On the other hand,
\begin{align*}
J_2& \preceq \int_{\{|x-y|>R_1\}}\big(\rho^{x,0}_1(t,x-y)+\rho^{y,0}_1(t,x-y)\big)\,dy\\
&\preceq \int_{\{|x-y|>R_1\}}\bigg(\frac{t}{|x-y|^{d+\alpha(x)}}+\frac{t}{|x-y|^{d+\alpha(y)}}\bigg)\,dy\preceq t \int_{\{|x-y|>R_1\}}\frac{1}{|x-y|^{d+\alpha_1}}\,dy \preceq t.
\end{align*}

Furthermore, following the argument of Lemma \ref{l1-1}, we can derive that for every $t\in (0,1]$ and $x,y \in \mathds R^d$
\begin{equation} \begin{split}
&\int_{\mathds R^d} \left[\left(t^{-{2}/{\alpha(x)}}|z|^2\right)\wedge 1\right]
\cdot \rho_{1}^{x,0}(t,y \pm z)\cdot |z|^{-d-\alpha(x)}\,dz
\preceq \rho^{x,0}_{0}(t,y),\\
&\int_{\mathds R^d} \left[\left(t^{-{2}/{\alpha(x)}}|z|^2\right)\wedge 1\right]
\cdot \rho_{1}^{x,0}(t,y)\cdot |z|^{-d-\alpha(x)}\,dz
\preceq \rho^{x,0}_{0}(t,y).
\end{split}
\end{equation}

Since \eqref{l3-2-1-} holds true for $\tilde \rho$ as mentioned in Remark \ref{r3-3}(2),
for every $0<\theta<\alpha_1$ and $0<\gamma<({\theta}/{\alpha_2})\wedge ((1-({\theta}/{\alpha_1}))/2)$, we have
\begin{equation} \begin{split}
J_{11}&\preceq \tilde \rho^{x,0}_0(t,x-y) \int_0^{{t}/{2}}\big(s^{-1-\gamma+({\theta}/{\alpha_2})}(t-s)^{-\gamma-({\theta}/{\alpha_1})}
+s^{-\gamma}(t-s)^{-1-\gamma-({\theta}/{\alpha_1})}\big)\,ds\\
&\preceq \tilde \rho^{x,0}_0(t,x-y) \bigg(t^{-\gamma-({\theta}/{\alpha_1})}\int_0^{{t}/{2}}s^{-1-\gamma+({\theta}/{\alpha_2})}\,ds+
t^{-1-\gamma-({\theta}/{\alpha_1})}\int_0^{{t}/{2}} s^{-\gamma}\,ds\bigg)\\
& \preceq  \tilde \rho^{x,0}_{-2\gamma-({\theta}/{\alpha_1})}(t,x-y).
\end{split}
\end{equation}

Hence, we find that for every $t\in (0,1]$ and $x,y \in \mathds R^d$ with $|x-y|\leqslant R_1$,
\begin{equation*}
J_1 \preceq \tilde \rho^{x,\beta_0}_{-2\gamma-({\theta}/{\alpha_1})}(t,x-y).
\end{equation*}

We assume that $\beta_0<\alpha_2$ and $\beta_0^*=\beta_0$ for simplicity.
Observe that
\begin{align*}
 \int_{\mathds R^d}  {\mathcal L}^xp^y(t,x-y)\,dy
&=\int_{\mathds R^d}\big( {\mathcal L}^xp^y(t,x-y)- {\mathcal L}^xp^x(t,x-y)\big)\,dy\\
&=\int_{\mathds R^d}
\int_{\mathds R^d}\big(\delta_{p^y}(t,x-y;z)
-\delta_{p^x}(t,x-y;z)\big)\cdot\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz\,dy.
\end{align*}
Therefore, for all $t\in (0,1]$ and $x\in \mathds R^d$,
\begin{align*}
 \Big|\int_{\mathds R^d}  {\mathcal L}^xp^y(t,x-y)\,dy\Big|
&\preceq \int_{\{|y-x|\leqslant R_1\}}\int_{\mathds R^d}
|\delta_{p^y}(t,x-y;z)
-\delta_{p^x}(t,x-y;z)|\cdot \frac{1}{|z|^{d+\alpha(x)}}\,dz\,dy\\
&\quad+\int_{\{|y-x|>R_1\}}\int_{\mathds R^d}|\delta_{p^y}(t,x-y;z)
-\delta_{p^x}(t,x-y;z)|\cdot \frac{1}{|z|^{d+\alpha(x)}}\,dz\,dy\\
&=:J_1+J_2,
\end{align*}
where $R_1$ is the constant in Lemma \ref{l4-2}.
According to \eqref{l4-2-1}, we have for all $t\in (0,1]$ and $x\in \mathds R^d$,
\begin{align*}
J_1& \preceq \int_{\{|y-x|\leqslant R_1\}}\tilde \rho^{x,\beta_0}_{-2\gamma-({\theta}/{\alpha_1})}(t,x-y)\,dy
\preceq t^{-1+(\beta_0^*/\alpha_2)-2\gamma-({\theta}/{\alpha_1})},
\end{align*}
where we used the fact that \eqref{l3-1-1-00} holds for $\tilde \rho$.

(1) Suppose that $\kappa(x,z)$ is independent of $z$. Then, according to the argument for $J_1$ in  \eqref{l2-1-3a}, for every $t \in (0,1]$ and $x,y\in \mathds R^d$ with $|x-y|>R_1$,
\begin{equation} \begin{split}
&\int_{\mathds R^d}|\delta_{p^y}(t,x-y;z)|\cdot \frac{1}{|z|^{d+\alpha(x)}}\,dz\preceq \frac{1}{|x-y|^{d+\alpha_1}},\\
& \int_{\mathds R^d}|\delta_{p^x}(t,x-y;z)|\cdot \frac{1}{|z|^{d+\alpha(x)}}\,dz\preceq \frac{1}{|x-y|^{d+\alpha_1}},\end{split}
\end{equation}
which imply that for all $t\in (0,1]$ and $x\in \mathds R^d$,
\begin{align*}
J_2&\preceq \int_{\{|y-x|>R_2\}}\int_{\mathds R^d}
|\delta_{p^y}(t,x-y;z)|\cdot \frac{1}{|z|^{d+\alpha(x)}}\,dz\,dy +\int_{\{|y-x|>R_2\}}\int_{\mathds R^d}
|\delta_{p^x}(t,x-y;z)|\cdot \frac{1}{|z|^{d+\alpha(x)}}\,dz\,dy\\
&\leqslant C_1.
\end{align*}
Combining both the estimates for $J_1$ and $J_2$, we prove \eqref{p4-2-1}.

(2) When $\kappa(x,z)$ depends on $z$, by the argument of \eqref{l2-1-5}, the first inequality in \eqref{p4-2-2} will be changed into
\begin{equation*}
\int_{\mathds R^d}|\delta_{p^y}(t,x-y;z)|\cdot \frac{1}{|z|^{d+\alpha(x)}}\,dz\preceq
\frac{t^{1-{(\alpha_2/\alpha_1)}}}{|x-y|^{d+\alpha_1}}.
\end{equation*}
Using this inequality and following the same line as above, we will obtain \eqref{p4-2-1a}.

{(1)} We first assume that $\kappa(x,z)$ is independent of $z$. The proof is split into four parts.

{(i)} For every $0<s<t<1$ and $x,y \in \mathds R^d$, define
\begin{equation*}
\phi(t,s,x,y):=\int_{\mathds R^d}p^z(t-s,x-z)q(s,z,y)\,dz,
\end{equation*}
where $q(t,x,y)$ is constructed in Proposition \ref{p3-1}.
By \eqref{eq2-1}, it holds that
\begin{equation} p(t,x,y)=p^y(t,x-y)+\int_0^t \phi(t,s,x,y)\,ds.
\end{equation}

Note that for every $t \in (0,1]$, $x,y\in \mathds R^d$ and $\varepsilon>0$,
\begin{align*}
 \frac{1}{\varepsilon}\int_t^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-q(t,x,y)
&= \frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\mathds R^d}p^z(t+\varepsilon-s,x-z)q(s,z,y)\,dz\,ds-q(t,x,y)\\
&=\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\mathds R^d}p^z(t+\varepsilon-s,x-z)\big(
q(s,z,y)-q(s,x,y)\big)\,dz\,ds\\
&\quad +\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\bigg(
\int_{\mathds R^d} p^z(t+\varepsilon-s,x-z)\,dz\bigg)\cdot \big(q(s,x,y)-q(t,x,y)\big)\,ds\\
&\quad +q(t,x,y)\cdot\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\bigg(\int_{\mathds R^d} p^z(t+\varepsilon-s,x-z)\,dz-1\bigg)\,ds\\
&=:J_1(\varepsilon)+J_2(\varepsilon)+J_3(\varepsilon).
\end{align*}

First, by \eqref{p3-1-1a}, for every $t>0$, $x,y \in \mathds R^d$ and $\sigma>0$, there exists
a constant $\varepsilon_1:=\varepsilon_1(t,x,y, \sigma)>0$ such that for all $z\in \mathds R^d$ with $|z-x|\leqslant \varepsilon_1$,
\begin{equation} |q(s,z,y)-q(s,x,y)|\leqslant \sigma
\end{equation} holds for all $t<s<t+\varepsilon$ and $0<\varepsilon<1$.
Let
\begin{align*}
|J_1(\varepsilon)|&\preceq \frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\{|z-x|\leqslant \varepsilon_1\}}p^z(t+\varepsilon-s,x-z)\big|
q(s,z,y)-q(s,x,y)\big|\,dz\,ds\\
&\quad +\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\{|z-x|>\varepsilon_1\}}p^z(t+\varepsilon-s,x-z)\big|
q(s,z,y)-q(s,x,y)\big|\,dz\,ds\\
&=:J_{11}(\varepsilon)+J_{12}(\varepsilon).
\end{align*}
According to \eqref{t4-1-2} and \eqref{l3-1-1}, we know immediately that
\begin{align*}
J_{11}(\varepsilon)&\preceq \sigma\cdot\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\mathds R^d}\rho^{z,0}_{1}
(t+\varepsilon-s,x-z)\,dz\,ds\preceq \frac{\sigma}{\varepsilon}\cdot \int_t^{t+\varepsilon}\,ds \leqslant C_1 \sigma,
\end{align*}
where $C_1>0$ is a constant independent of $\varepsilon$ and $\sigma$.
At the same time, it holds that for any $\gamma<{\beta_0}/{\alpha_2},$
\begin{align*}
|J_{12}(\varepsilon)|&\preceq \frac{1}{\varepsilon}\cdot\bigg(
\int_t^{t+\varepsilon}\big(t+\varepsilon-s\big) \int_{\{|z-x|>\varepsilon_1\}}
\frac{|q(s,z,y)|+|q(s,x,y)|}{|x-z|^{d+\alpha_1}}\,dz\,ds\bigg)\\
&\preceq \varepsilon_1^{-d-\alpha_1}\int_t^{t+\varepsilon}
\int_{\mathds R^d}\big(\rho^{y,0}_{({\beta_0}/{\alpha_2})-\gamma}+\rho^{y,\beta_0}_{-\gamma}\big)(s,z-y)\,dz\,ds\\
&\quad +\int_t^{t+\varepsilon}\int_{\{|z-x|>\varepsilon_1\}}
\frac{\big(\rho^{y,0}_{({\beta_0}/{\alpha_2})-\gamma}+\rho^{y,\beta_0}_{-\gamma}\big)(s,x-y)}{|z-x|^{d+\alpha_1}}\,dz\,ds\\
&\preceq \varepsilon_1^{-d-\alpha_1}\bigg(
\int_t^{t+\varepsilon}s^{-1+({\beta_0}/{\alpha_2})-\gamma}\,ds+\varepsilon_1^d t^{-1-({d}/{\alpha_1})-\gamma} \int_t^{t+\varepsilon}\,ds\bigg)\\
&\leqslant C(\varepsilon_1)t^{-1-({d}/{\alpha_1})-\gamma}\varepsilon,
\end{align*}
where in the first inequality we used the fact that $p^z(t,x)\preceq \frac{t}{|x|^{d+\alpha_1}}$ for every
$t \in (0,1]$ and $x\in \mathds R^d$ with $|x|>\varepsilon_1$, the second inequality follows from \eqref{p3-1-1}, and in the third inequality we used \eqref{l3-1-1-00} and the fact
that $\rho^{y,0}_{-\gamma}(s,x)\preceq t^{-1-({d}/{\alpha_1})-\gamma}$ for all $t<s<t+\varepsilon$ and $x\in \mathds R^d$.

Second, note that for every fixed $x,y \in \mathds R^d$,
$q_0(\cdot,x,y)$ is continuous in $(0,1]$. Then, by \eqref{eq2-2}, \eqref{p3-1-1} and the dominated convergence theorem,
we know that $q(\cdot,x,y)$ is continuous in $(0,1]$. Thus, for every $t \in (0,1]$, $x,y \in \mathds R^d$ and $\sigma>0$, there exists a constant $\varepsilon_2:=\varepsilon_2(t,x,y,\sigma)>0$ such that for all $|s-t|<\varepsilon_2$,
\begin{equation*}
|q(s,x,y)-q(t,x,y)|\leqslant \sigma,
\end{equation*}
from which we have that when $\varepsilon<\varepsilon_2$,
\begin{align*}
|J_2(\varepsilon)|&\preceq \frac{\sigma}{\varepsilon}\cdot
\Big(\int_t^{t+\varepsilon}\Big|\int_{\mathds R^d}p^z(t+\varepsilon-s,x-z)\,dz\Big|\,ds\Big)\leqslant C_2\sigma,
\end{align*}
where in the last inequality we have used Lemma \ref{p4-1}, and
$C_2>0$ is a constant independent of $\varepsilon$ and $\sigma$.

Third, according to Lemma \ref{p4-1}, we arrive at
\begin{align*}
\lim_{\varepsilon \downarrow 0}|J_3(\varepsilon)|&\leqslant
|q(t,x,y)|\cdot \bigg(\lim_{\varepsilon \downarrow 0}\frac{1}{\varepsilon}
\cdot \int_t^{t+\varepsilon}\Big|\int_{\mathds R^d}p^z(t+\varepsilon-s,x-z)\,dz-1\Big|\,ds\bigg)\\
&\leqslant |q(t,x,y)|\cdot\bigg(\lim_{\varepsilon \downarrow 0}\sup_{s \in (0,\varepsilon)}
\Big|\int_{\mathds R^d}p^z(s,x-z)\,dz-1\Big|\bigg)=0.
\end{align*}

Combining all the estimates together, we arrive at for every $\sigma>0$,
\begin{align*}
\lim_{\varepsilon \downarrow 0}\Big|\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-q(t,x,y)\Big|\leqslant C_3\sigma,
\end{align*}
where $C_3$ is independent of $\varepsilon$ and $\sigma$. Since $\sigma$ is arbitrary, we finally obtain that
\begin{equation} \begin{split}
\lim_{\varepsilon \downarrow 0}\Big|\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-q(t,x,y)\Big|=0.
\end{split}
\end{equation}

{(ii)} By the proof of \eqref{l4-2-3} (also see \cite[Theorem 2.4]{CZ}), it holds that
\begin{equation} | {\mathcal L}^zp^z(t-s,x-z)|\preceq \rho^{z,0}_0(t-s,x-z),
\end{equation} and so we can verify that for every $0<s<t<1$ and $x,y\in \mathds R^d$,
$$\int_{\mathds R^d}| {\mathcal L}^z p^z(t-s,x-z)||q(s,z,y)|\,dz<\infty.$$
Thus, by the dominated convergence theorem, for every $0<s<t$ and $x,y \in \mathds R^d$,
\begin{equation} \begin{split}
\partial_t \phi(t,s,x,y)&=\int_{\mathds R^d} {\mathcal L}^zp^z(t-s,x-z)q(s,z,y)\,dz\\
&=\int_{\mathds R^d} {\mathcal L}^zp^z(t-s,x-z)(q(s,z,y)-q(s,x,y))\,dz\\
&\quad +q(s,x,y)\int_{\mathds R^d}( {\mathcal L}^z- {\mathcal L}^x)p^z(t-s,x-z)\,dz\\
&\quad +q(s,x,y)\int_{\mathds R^d} {\mathcal L}^x p^z(t-s,x-z)\,dz\\
&=:\tilde J_1+ \tilde J_2+ \tilde J_3.
\end{split}
\end{equation}

Combining \eqref{t4-1-4} with \eqref{p3-1-1a} yields that for any $0<\gamma<\theta<{\beta_0}/{\alpha_2}$,
\begin{align*}
|\tilde J_1| &\preceq \int_{\mathds R^d}\tilde \rho^{z,\tilde \theta}_0(t-s,x-z)\cdot
\tilde \rho^{y,0}_{\theta-\gamma+({\beta_0}/{\alpha_2})-({\beta_0}/{\alpha_1})}(s,z-y)\,dz\\
&\quad +\int_{\mathds R^d}\tilde \rho^{z,\tilde \theta}_0(t-s,x-z)\cdot
\tilde \rho^{y,0}_{\theta-\gamma+({\beta_0}/{\alpha_2})-({\beta_0}/{\alpha_1})}(s,x-y)\,dz\\
&=:\tilde J_{11}+ \tilde J_{12},
\end{align*}
where $\tilde \theta:=\alpha_1(\beta_0-\alpha_2\theta)/{\alpha_2}$.
According to \eqref{l3-2-1} (which holds for $\tilde \rho$), we obtain that
for every ${t}/{2}\leqslant s \leqslant t$,
\begin{align*}
\tilde J_{11}&\preceq \tilde \rho^{y,0}_0(t,x-y)\cdot\big[(t-s)^{-1+({\tilde \theta}/{\alpha_2})}s^{\theta-\gamma+(\beta_0/\alpha_2)-({\beta_0}/{\alpha_1})-1}\big]\preceq t^{-\gamma-({\beta_0}/{\alpha_1})-({d}/{\alpha_1})-2}(t-s)^{-1+({\tilde \theta}/{\alpha_2})},
\end{align*}
where in the last inequality we have used the fact that $\tilde\rho^{y,0}_0(t,x-y)\preceq t^{-1-d/\alpha_1}$ and
$s^{-1}\preceq t^{-1}$ for ${t}/{2}\leqslant s \leqslant t$. Note that $\tilde \rho^{y,\beta_0}_{\theta-\gamma-({\beta_0}/{\alpha_1})}(s,x-y)\preceq t^{-\gamma-({\beta_0}/{\alpha_1})-({d}/{\alpha_1})-1}$ for
every ${t}/{2}\leqslant s \leqslant t$,
and \eqref{l3-1-1} holds for $\tilde \rho$, then we have
\begin{align*}
\tilde J_{12}& \preceq t^{-\gamma-({\beta_0}/{\alpha_1})-({d}/{\alpha_1})-1}\int_{\mathds R^d}\tilde \rho^{z,\tilde \theta}_{0}(t-s,x-z)\,dz\preceq t^{-\gamma-({\beta_0}/{\alpha_1})-({d}/{\alpha_1})-1}(t-s)^{-1+({\tilde \theta}/{\alpha_2})}.
\end{align*}

By \eqref{l2-1-2} and \eqref{p3-1-1}, we arrive at that for any $0<\gamma<\theta<{\beta_0}/{\alpha_2}$ and every
${t}/{2}\leqslant s \leqslant t$,
\begin{equation*}
|( {\mathcal L}^z- {\mathcal L}^x)p^z(t-s,x-z)|\preceq
|q_0(t-s,x, z)|\preceq \rho^{z,\beta_0}_{-\gamma}(t-s,x-z)
\end{equation*} and \begin{equation*}
|q(s,x,y)|\preceq \big(\rho^{y,0}_{({\beta_0}/{\alpha_2})-\gamma}+\rho^{y,\beta_0}_{-\gamma}\big)(s,x-y)\preceq t^{-\gamma-({d}/{\alpha_1})-1}.
\end{equation*}
Hence, combining both estimates above with \eqref{l3-1-1},  we obtain
\begin{align*}
|\tilde J_{2}|&\preceq t^{-\gamma-({d}/{\alpha_1})-1}\int_{\mathds R^d} \rho^{z,\beta_0}_{-\gamma}(t-s,x-z)\,dz
 \preceq t^{-\gamma-({d}/{\alpha_1})-1}(t-s)^{-1+({\beta_0}/{\alpha_2})-\gamma}.
\end{align*}
Furthermore, \eqref{p3-1-1} and \eqref{p4-2-1} yield that for every ${t}/{2}\leqslant s \leqslant t$ and
constants $\gamma,\theta \in (0,1)$ such that $\gamma<{\theta}/{\alpha_2}$ and
$2\gamma+({\theta}/{\alpha_1})<\beta_0/\alpha_2$,
\begin{equation*}
|\tilde J_3| \preceq t^{-\gamma-({d}/{\alpha_1})-1}(t-s)^{-1+({\beta_0}/{\alpha_2})-2\gamma-({\theta}/{\alpha_1})}.
\end{equation*}


On the other hand, when $0<s\leqslant {t}/{2}$,  it follows from \eqref{t4-1-4}, \eqref{p3-1-1} and \eqref{l3-2-1} that
\begin{align*}
\big|\partial_t \phi(t,s,x,y)\big|
 &\preceq
\int_{\mathds R^d}\big| {\mathcal L}^z p^z(t-s,x-z)\big|\big|q(s,z,y)\big|\,dz\\
&\preceq \int_{\mathds R^d} \rho^{z,0}_0(t-s,x-z)\cdot
\big(\rho^{y,0}_{({\beta_0}/{\alpha_2})-\gamma}+\rho^{y,\beta_0}_{-\gamma}\big)(s,z-y)\,dz\\
&\preceq \rho^{y,0}_0(t,x-y)\cdot\big[(t-s)^{-1}s^{({\beta_0}/{\alpha_2})-\gamma}+
(t-s)^{-1+({\beta_0}/{\alpha_2})}s^{-\gamma}+s^{-1+({\beta_0}/{\alpha_2})-\gamma}\big]\\
&\quad +\rho^{y,\beta_0}_{0}(t,x-y)\cdot(t-s)^{-1}s^{-\gamma}\\
&\preceq t^{-2-({d}/{\alpha_1})}s^{-1+({\beta_0}/{\alpha_2})-\gamma},
\end{align*}
where in the last inequality we have used the facts that $\rho^{y,0}_0(t,x-y)\preceq t^{-1-({d}/{\alpha_1})}$ and $(t-s)^{-1}\preceq t^{-1}$ for every
$0<s\leqslant {t}/{2}$.
Therefore, choosing $\gamma,\theta \in (0,1)$ such that $\gamma<{\theta}/{\alpha_2}$ and
$2\gamma+({\theta}/{\alpha_1})<\beta_0/\alpha_2$, and combining all the estimates above,  we
know that \eqref{e:lkk} is well defined, and that for every $t \in (0,1)$,
$
\sup_{t_0 \in (t,t+\varepsilon_1)}|
\partial_t\phi(t_0,s,x,y)|\leqslant \eta(t,s),
$
where $\eta$ is a non-negative measurable function such that
$\int_0^t \eta(t,s)\,ds<\infty$ and $\varepsilon_1>0$ is a constant small enough (which may depend on $t$).
Now, according to the dominated convergence theorem, for every $t \in (0,1]$ and $x,y\in \mathds R^d$,
\begin{equation} \begin{split}
\lim_{\varepsilon \downarrow 0}\frac{1}{\varepsilon}\cdot
\bigg(\int_0^t \big(\phi(t+\varepsilon,s,x,y)-\phi(t,s,x,y)\big)\,ds\bigg)=
\int_0^t \partial_t \phi(t,s,x,y)\,ds.
\end{split}
\end{equation}

{(iii)} We obtain by \eqref{t4-1-3} and \eqref{t4-1-5}  that for every $t \in (0,1)$ and $x,y \in \mathds R^d$,
\begin{align*}
&\lim_{\varepsilon \downarrow 0}\Bigg|\frac{1}{\varepsilon}
\cdot \Big(\int_0^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-
\int_0^{t}\phi(t,s,x,y)\,ds\Big)-q(t,x,y)-\int_0^t \partial_t \phi(t,s,x,y)\,ds\Bigg|\\
&\leqslant \lim_{\varepsilon \downarrow 0}\Bigg|\frac{1}{\varepsilon}\cdot\Big(\int_t^{t+\varepsilon}
\phi(t+\varepsilon,s,x,y)\,ds\Big)-q(t,x,y)\Bigg|\\
&\quad+\lim_{\varepsilon \downarrow 0}\Bigg|\frac{1}{\varepsilon}\cdot\Big(\int_0^{t}
(\phi(t+\varepsilon,s,x,y)-\phi(t,s,x,y))\,ds\Big)-\int_0^t \partial_t \phi(t,s,x,y)\,ds\Bigg|\\
&=0.
\end{align*}
By the same way, it is not difficult to verify
\begin{align*}
&\lim_{\varepsilon \uparrow 0}\Bigg|\frac{1}{\varepsilon}
\cdot \Big(\int_0^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-
\int_0^{t}\phi(t,s,x,y)\,ds\Big)-q(t,x,y)-\int_0^t \partial_t \phi(t,s,x,y)\,ds\Bigg|=0.
\end{align*}
Hence, we have for any $t_0\in (0,1]$ and $x,y\in \mathds R^d$,
\begin{equation*}
\partial_t\left(\int_0^{\cdot}\phi(\cdot,s,x,y)\,ds\right)(t_0)=q(t_0,x,y)+\int_0^{t_0}\partial_t \phi(t_0,s,x,y)\,ds.
\end{equation*}

Combining all estimates above with \eqref{t4-1-1}, \eqref{eq2-2} and \eqref{e:lkk},
we have for every $t \in (0,1]$ and $x,y \in \mathds R^d$,
\begin{equation} \begin{split}
\frac{\partial p(t,x,y)}{\partial t}
&= {\mathcal L}^y p^y(t,x-y)+q(t,x,y)+\int_0^t \partial_t \phi(t,s,x,y)\,ds\\
&= {\mathcal L}^y p^y(t,x-y)+( {\mathcal L}^x- {\mathcal L}^y)p^y(t,x-y)\\
&\quad +\int_0^t
\int_{\mathds R^d}( {\mathcal L}^x- {\mathcal L}^z)p^z(t-s,x-z)\cdot q(s,z,y)\,dz\,ds\\
&\quad +\int_0^t \int_{\mathds R^d} {\mathcal L}^z p^z(t-s,x-z)q(s,z,y)\,dz\,ds\\
&= {\mathcal L}^x p^y(t,x-y)+\int_0^t\int_{\mathds R^d} {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)\,dz\,ds.
\end{split}
\end{equation}


Furthermore, by the same arguments for estimates of $\tilde J_1$, $\tilde J_2$ and $\tilde J_3$ above, we have
\begin{equation} \begin{split}
& \int_0^t\int_{\mathds R^d}|  {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)|\,dz\,ds\\
&\preceq \int_0^t\int_{\mathds R^d}\big|  {\mathcal L}^z p^z(t-s,x-z)q(s,z,y)\big|\,dz\,ds+\int_0^t \int_{\mathds R^d}|( {\mathcal L}^x- {\mathcal L}^z) p^z(t-s,x-z)q(s,z,y)|\,dz\,ds\\
&<\infty
\end{split}
\end{equation} and so
$$\int_0^t {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds= \int_0^t\int_{\mathds R^d}  {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)\,dz\,ds,$$ which in turn implies that \eqref{t4-1-6} is well defined.

{(iv)} For any $\varepsilon,\sigma>0$ small enough,
\begin{align*}
&\int_{\{|z|>\sigma\}}\delta_{\int_0^t\phi(t,s,\cdot,y)\,ds}(x;z)\cdot\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz\\
&=\int_{\varepsilon}^{t-\varepsilon} \int_{\{|z|>\sigma\}}\delta_{\phi(t,s,\cdot,y)}(x;z)\cdot\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz
\,ds +\int_{\{(0,\varepsilon)\cup(t-\varepsilon,t)\}}
\int_{\{|z|>\sigma\}}\delta_{\phi(t,s,\cdot,y)}(x;z)\cdot\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz
\,ds\\
&=:\widehat J_1(\varepsilon,\sigma)+\widehat J_2(\varepsilon,\sigma).
\end{align*}
Note that for the integral with respect to time variable in $\widehat J_1(\varepsilon,\sigma)$, there is not any
singularity. According to the dominated convergence theorem,  we have
\begin{align*}
\lim_{\sigma \downarrow 0}J_1(\varepsilon,\sigma)&=\int_{\varepsilon}^{t-\varepsilon}
 {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds=\int_{\varepsilon}^{t-\varepsilon}\int_{\mathds R^d} {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)\,dz\,ds,
\end{align*}
Meanwhile, according to the proof of \eqref{t4-1-7a} and Fatou's lemma we arrive at
\begin{equation*}
\limsup_{\sigma \downarrow 0}|\widehat J_2(\varepsilon,\sigma)|\leqslant
\int_{\{(0,\varepsilon)\cup(t-\varepsilon,t)\}}| {\mathcal L}^x(\phi(t,s,\cdot,y)(x)|\,ds.
\end{equation*}
Hence, combining all the estimates above with \eqref{e2-3} yields
\begin{align*}
&\Big| {\mathcal L}^x\Big(\int_0^t \phi(t,s,\cdot,y)\,ds\Big)(x)-
\int_0^t  {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds\Big|\\
&\leqslant \limsup_{\sigma \downarrow 0}\bigg|\int_{\{|z|>\sigma\}}\delta_{\int_0^t\phi(t,s,\cdot,y)\,ds}(x;z)\cdot\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz
-\int_0^t  {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds \bigg|\\
&\leqslant 2\int_{\{(0,\varepsilon)\cup(t-\varepsilon,t)\}}| {\mathcal L}^x(\phi(t,s,\cdot,y))(x)|\,ds.
\end{align*}
Then, letting $\varepsilon \rightarrow 0$, we know that for every $t \in (0,1)$ and $x,y\in \mathds R^d$,
\begin{align*}
 {\mathcal L}^x\Big(\int_0^t \phi(t,s,\cdot,y)\,ds\Big)(x)
&=\int_0^t  {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds=
\int_0^t\int_{\mathds R^d} {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)\,dz\,ds,
\end{align*}
which along with \eqref{t4-1-6} yields \eqref{t1-1-1} immediately.

{(i)} For every $0<s<t<1$ and $x,y \in \mathds R^d$, define
\begin{equation*}
\phi(t,s,x,y):=\int_{\mathds R^d}p^z(t-s,x-z)q(s,z,y)\,dz,
\end{equation*}
where $q(t,x,y)$ is constructed in Proposition \ref{p3-1}.
By \eqref{eq2-1}, it holds that
\begin{equation} p(t,x,y)=p^y(t,x-y)+\int_0^t \phi(t,s,x,y)\,ds.
\end{equation}

Note that for every $t \in (0,1]$, $x,y\in \mathds R^d$ and $\varepsilon>0$,
\begin{align*}
 \frac{1}{\varepsilon}\int_t^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-q(t,x,y)
&= \frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\mathds R^d}p^z(t+\varepsilon-s,x-z)q(s,z,y)\,dz\,ds-q(t,x,y)\\
&=\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\mathds R^d}p^z(t+\varepsilon-s,x-z)\big(
q(s,z,y)-q(s,x,y)\big)\,dz\,ds\\
&\quad +\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\bigg(
\int_{\mathds R^d} p^z(t+\varepsilon-s,x-z)\,dz\bigg)\cdot \big(q(s,x,y)-q(t,x,y)\big)\,ds\\
&\quad +q(t,x,y)\cdot\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\bigg(\int_{\mathds R^d} p^z(t+\varepsilon-s,x-z)\,dz-1\bigg)\,ds\\
&=:J_1(\varepsilon)+J_2(\varepsilon)+J_3(\varepsilon).
\end{align*}

First, by \eqref{p3-1-1a}, for every $t>0$, $x,y \in \mathds R^d$ and $\sigma>0$, there exists
a constant $\varepsilon_1:=\varepsilon_1(t,x,y, \sigma)>0$ such that for all $z\in \mathds R^d$ with $|z-x|\leqslant \varepsilon_1$,
\begin{equation} |q(s,z,y)-q(s,x,y)|\leqslant \sigma
\end{equation} holds for all $t<s<t+\varepsilon$ and $0<\varepsilon<1$.
Let
\begin{align*}
|J_1(\varepsilon)|&\preceq \frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\{|z-x|\leqslant \varepsilon_1\}}p^z(t+\varepsilon-s,x-z)\big|
q(s,z,y)-q(s,x,y)\big|\,dz\,ds\\
&\quad +\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\{|z-x|>\varepsilon_1\}}p^z(t+\varepsilon-s,x-z)\big|
q(s,z,y)-q(s,x,y)\big|\,dz\,ds\\
&=:J_{11}(\varepsilon)+J_{12}(\varepsilon).
\end{align*}
According to \eqref{t4-1-2} and \eqref{l3-1-1}, we know immediately that
\begin{align*}
J_{11}(\varepsilon)&\preceq \sigma\cdot\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\int_{\mathds R^d}\rho^{z,0}_{1}
(t+\varepsilon-s,x-z)\,dz\,ds\preceq \frac{\sigma}{\varepsilon}\cdot \int_t^{t+\varepsilon}\,ds \leqslant C_1 \sigma,
\end{align*}
where $C_1>0$ is a constant independent of $\varepsilon$ and $\sigma$.
At the same time, it holds that for any $\gamma<{\beta_0}/{\alpha_2},$
\begin{align*}
|J_{12}(\varepsilon)|&\preceq \frac{1}{\varepsilon}\cdot\bigg(
\int_t^{t+\varepsilon}\big(t+\varepsilon-s\big) \int_{\{|z-x|>\varepsilon_1\}}
\frac{|q(s,z,y)|+|q(s,x,y)|}{|x-z|^{d+\alpha_1}}\,dz\,ds\bigg)\\
&\preceq \varepsilon_1^{-d-\alpha_1}\int_t^{t+\varepsilon}
\int_{\mathds R^d}\big(\rho^{y,0}_{({\beta_0}/{\alpha_2})-\gamma}+\rho^{y,\beta_0}_{-\gamma}\big)(s,z-y)\,dz\,ds\\
&\quad +\int_t^{t+\varepsilon}\int_{\{|z-x|>\varepsilon_1\}}
\frac{\big(\rho^{y,0}_{({\beta_0}/{\alpha_2})-\gamma}+\rho^{y,\beta_0}_{-\gamma}\big)(s,x-y)}{|z-x|^{d+\alpha_1}}\,dz\,ds\\
&\preceq \varepsilon_1^{-d-\alpha_1}\bigg(
\int_t^{t+\varepsilon}s^{-1+({\beta_0}/{\alpha_2})-\gamma}\,ds+\varepsilon_1^d t^{-1-({d}/{\alpha_1})-\gamma} \int_t^{t+\varepsilon}\,ds\bigg)\\
&\leqslant C(\varepsilon_1)t^{-1-({d}/{\alpha_1})-\gamma}\varepsilon,
\end{align*}
where in the first inequality we used the fact that $p^z(t,x)\preceq \frac{t}{|x|^{d+\alpha_1}}$ for every
$t \in (0,1]$ and $x\in \mathds R^d$ with $|x|>\varepsilon_1$, the second inequality follows from \eqref{p3-1-1}, and in the third inequality we used \eqref{l3-1-1-00} and the fact
that $\rho^{y,0}_{-\gamma}(s,x)\preceq t^{-1-({d}/{\alpha_1})-\gamma}$ for all $t<s<t+\varepsilon$ and $x\in \mathds R^d$.

Second, note that for every fixed $x,y \in \mathds R^d$,
$q_0(\cdot,x,y)$ is continuous in $(0,1]$. Then, by \eqref{eq2-2}, \eqref{p3-1-1} and the dominated convergence theorem,
we know that $q(\cdot,x,y)$ is continuous in $(0,1]$. Thus, for every $t \in (0,1]$, $x,y \in \mathds R^d$ and $\sigma>0$, there exists a constant $\varepsilon_2:=\varepsilon_2(t,x,y,\sigma)>0$ such that for all $|s-t|<\varepsilon_2$,
\begin{equation*}
|q(s,x,y)-q(t,x,y)|\leqslant \sigma,
\end{equation*}
from which we have that when $\varepsilon<\varepsilon_2$,
\begin{align*}
|J_2(\varepsilon)|&\preceq \frac{\sigma}{\varepsilon}\cdot
\Big(\int_t^{t+\varepsilon}\Big|\int_{\mathds R^d}p^z(t+\varepsilon-s,x-z)\,dz\Big|\,ds\Big)\leqslant C_2\sigma,
\end{align*}
where in the last inequality we have used Lemma \ref{p4-1}, and
$C_2>0$ is a constant independent of $\varepsilon$ and $\sigma$.

Third, according to Lemma \ref{p4-1}, we arrive at
\begin{align*}
\lim_{\varepsilon \downarrow 0}|J_3(\varepsilon)|&\leqslant
|q(t,x,y)|\cdot \bigg(\lim_{\varepsilon \downarrow 0}\frac{1}{\varepsilon}
\cdot \int_t^{t+\varepsilon}\Big|\int_{\mathds R^d}p^z(t+\varepsilon-s,x-z)\,dz-1\Big|\,ds\bigg)\\
&\leqslant |q(t,x,y)|\cdot\bigg(\lim_{\varepsilon \downarrow 0}\sup_{s \in (0,\varepsilon)}
\Big|\int_{\mathds R^d}p^z(s,x-z)\,dz-1\Big|\bigg)=0.
\end{align*}

Combining all the estimates together, we arrive at for every $\sigma>0$,
\begin{align*}
\lim_{\varepsilon \downarrow 0}\Big|\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-q(t,x,y)\Big|\leqslant C_3\sigma,
\end{align*}
where $C_3$ is independent of $\varepsilon$ and $\sigma$. Since $\sigma$ is arbitrary, we finally obtain that
\begin{equation} \begin{split}
\lim_{\varepsilon \downarrow 0}\Big|\frac{1}{\varepsilon}\int_t^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-q(t,x,y)\Big|=0.
\end{split}
\end{equation}

{(iii)} We obtain by \eqref{t4-1-3} and \eqref{t4-1-5}  that for every $t \in (0,1)$ and $x,y \in \mathds R^d$,
\begin{align*}
&\lim_{\varepsilon \downarrow 0}\Bigg|\frac{1}{\varepsilon}
\cdot \Big(\int_0^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-
\int_0^{t}\phi(t,s,x,y)\,ds\Big)-q(t,x,y)-\int_0^t \partial_t \phi(t,s,x,y)\,ds\Bigg|\\
&\leqslant \lim_{\varepsilon \downarrow 0}\Bigg|\frac{1}{\varepsilon}\cdot\Big(\int_t^{t+\varepsilon}
\phi(t+\varepsilon,s,x,y)\,ds\Big)-q(t,x,y)\Bigg|\\
&\quad+\lim_{\varepsilon \downarrow 0}\Bigg|\frac{1}{\varepsilon}\cdot\Big(\int_0^{t}
(\phi(t+\varepsilon,s,x,y)-\phi(t,s,x,y))\,ds\Big)-\int_0^t \partial_t \phi(t,s,x,y)\,ds\Bigg|\\
&=0.
\end{align*}
By the same way, it is not difficult to verify
\begin{align*}
&\lim_{\varepsilon \uparrow 0}\Bigg|\frac{1}{\varepsilon}
\cdot \Big(\int_0^{t+\varepsilon}\phi(t+\varepsilon,s,x,y)\,ds-
\int_0^{t}\phi(t,s,x,y)\,ds\Big)-q(t,x,y)-\int_0^t \partial_t \phi(t,s,x,y)\,ds\Bigg|=0.
\end{align*}
Hence, we have for any $t_0\in (0,1]$ and $x,y\in \mathds R^d$,
\begin{equation*}
\partial_t\left(\int_0^{\cdot}\phi(\cdot,s,x,y)\,ds\right)(t_0)=q(t_0,x,y)+\int_0^{t_0}\partial_t \phi(t_0,s,x,y)\,ds.
\end{equation*}

Combining all estimates above with \eqref{t4-1-1}, \eqref{eq2-2} and \eqref{e:lkk},
we have for every $t \in (0,1]$ and $x,y \in \mathds R^d$,
\begin{equation} \begin{split}
\frac{\partial p(t,x,y)}{\partial t}
&= {\mathcal L}^y p^y(t,x-y)+q(t,x,y)+\int_0^t \partial_t \phi(t,s,x,y)\,ds\\
&= {\mathcal L}^y p^y(t,x-y)+( {\mathcal L}^x- {\mathcal L}^y)p^y(t,x-y)\\
&\quad +\int_0^t
\int_{\mathds R^d}( {\mathcal L}^x- {\mathcal L}^z)p^z(t-s,x-z)\cdot q(s,z,y)\,dz\,ds\\
&\quad +\int_0^t \int_{\mathds R^d} {\mathcal L}^z p^z(t-s,x-z)q(s,z,y)\,dz\,ds\\
&= {\mathcal L}^x p^y(t,x-y)+\int_0^t\int_{\mathds R^d} {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)\,dz\,ds.
\end{split}
\end{equation}


Furthermore, by the same arguments for estimates of $\tilde J_1$, $\tilde J_2$ and $\tilde J_3$ above, we have
\begin{equation} \begin{split}
& \int_0^t\int_{\mathds R^d}|  {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)|\,dz\,ds\\
&\preceq \int_0^t\int_{\mathds R^d}\big|  {\mathcal L}^z p^z(t-s,x-z)q(s,z,y)\big|\,dz\,ds+\int_0^t \int_{\mathds R^d}|( {\mathcal L}^x- {\mathcal L}^z) p^z(t-s,x-z)q(s,z,y)|\,dz\,ds\\
&<\infty
\end{split}
\end{equation} and so
$$\int_0^t {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds= \int_0^t\int_{\mathds R^d}  {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)\,dz\,ds,$$ which in turn implies that \eqref{t4-1-6} is well defined.

{(iv)} For any $\varepsilon,\sigma>0$ small enough,
\begin{align*}
&\int_{\{|z|>\sigma\}}\delta_{\int_0^t\phi(t,s,\cdot,y)\,ds}(x;z)\cdot\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz\\
&=\int_{\varepsilon}^{t-\varepsilon} \int_{\{|z|>\sigma\}}\delta_{\phi(t,s,\cdot,y)}(x;z)\cdot\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz
\,ds +\int_{\{(0,\varepsilon)\cup(t-\varepsilon,t)\}}
\int_{\{|z|>\sigma\}}\delta_{\phi(t,s,\cdot,y)}(x;z)\cdot\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz
\,ds\\
&=:\widehat J_1(\varepsilon,\sigma)+\widehat J_2(\varepsilon,\sigma).
\end{align*}
Note that for the integral with respect to time variable in $\widehat J_1(\varepsilon,\sigma)$, there is not any
singularity. According to the dominated convergence theorem,  we have
\begin{align*}
\lim_{\sigma \downarrow 0}J_1(\varepsilon,\sigma)&=\int_{\varepsilon}^{t-\varepsilon}
 {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds=\int_{\varepsilon}^{t-\varepsilon}\int_{\mathds R^d} {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)\,dz\,ds,
\end{align*}
Meanwhile, according to the proof of \eqref{t4-1-7a} and Fatou's lemma we arrive at
\begin{equation*}
\limsup_{\sigma \downarrow 0}|\widehat J_2(\varepsilon,\sigma)|\leqslant
\int_{\{(0,\varepsilon)\cup(t-\varepsilon,t)\}}| {\mathcal L}^x(\phi(t,s,\cdot,y)(x)|\,ds.
\end{equation*}
Hence, combining all the estimates above with \eqref{e2-3} yields
\begin{align*}
&\Big| {\mathcal L}^x\Big(\int_0^t \phi(t,s,\cdot,y)\,ds\Big)(x)-
\int_0^t  {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds\Big|\\
&\leqslant \limsup_{\sigma \downarrow 0}\bigg|\int_{\{|z|>\sigma\}}\delta_{\int_0^t\phi(t,s,\cdot,y)\,ds}(x;z)\cdot\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz
-\int_0^t  {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds \bigg|\\
&\leqslant 2\int_{\{(0,\varepsilon)\cup(t-\varepsilon,t)\}}| {\mathcal L}^x(\phi(t,s,\cdot,y))(x)|\,ds.
\end{align*}
Then, letting $\varepsilon \rightarrow 0$, we know that for every $t \in (0,1)$ and $x,y\in \mathds R^d$,
\begin{align*}
 {\mathcal L}^x\Big(\int_0^t \phi(t,s,\cdot,y)\,ds\Big)(x)
&=\int_0^t  {\mathcal L}^x(\phi(t,s,\cdot,y))(x)\,ds=
\int_0^t\int_{\mathds R^d} {\mathcal L}^x p^z(t-s,x-z)q(s,z,y)\,dz\,ds,
\end{align*}
which along with \eqref{t4-1-6} yields \eqref{t1-1-1} immediately.

Throughout the proof, the constant $C$ denotes a positive constant that is independent of $R$
and $x$  whose exact value may change from line to line. Since \eqref{t4-3-1} holds, it suffices to prove that
for any $\varepsilon \in (0,1)$ and $t\in (\varepsilon,1]$,
\begin{equation} \sup_{x \in \mathds R^d}u(t,x)\leqslant \sup_{x \in \mathds R^d}u(\varepsilon,x).
\end{equation}

For every $R>1$, we can choose a smooth cut-off function $l_R:\mathds R^d \rightarrow \mathds R$ such that
\begin{equation*}
l_R(x)=
\begin{cases}
1,\ \ \   & |x|\leqslant R,\\
\in [0,1],\ & R<|x|<2R,\\
0,\ \ \  &|x|\geqslant 2R,
\end{cases}
\end{equation*} and
\begin{equation} |\nabla l_R(x)|^2+|\nabla^2 l_R(x)|\leqslant \frac{C}{R^2},\quad x\in \mathds R^d.
\end{equation}

Observe that
\begin{align*}
& {\mathcal L}(u\cdot l_R)(t,x)- {\mathcal L} u(t,x)\cdot l_R(x)-{\mathcal L} l_R(x)\cdot u(t,x)\\
&=\int_{\mathds R^d}(u(t,x+z)-u(t,x))\cdot (l_R(x+z)-l_R(x))
\frac{\kappa(x,z)}{|z|^{d+\alpha(x)}}\,dz\\
&\preceq \int_{\{|z|\leqslant 1\}}
(u(t,x+z)-u(t,x))\cdot (l_R(x+z)-l_R(x))
\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&\quad +\int_{\{|z|> 1\}}
(u(t,x+z)-u(t,x))\cdot (l_R(x+z)-l_R(x))
\frac{1}{|z|^{d+\alpha(x)}}\,dz\\
&=:J_1+J_2.
\end{align*}

On the one hand, by \eqref{t4-3-2} and \eqref{t4-3-6},
\begin{align*}
J_1&\leqslant \frac{C(\varepsilon)}{R}\int_{\{|z|\leqslant 1\}}
\frac{|z|^{1+\theta(x)}}{|z|^{d+\alpha(x)}}\,dz\leqslant \frac{C(\varepsilon)}{R},
\end{align*}
where in the last inequality we used $\inf_{x \in \mathds R^d}\big(\theta(x)+1-\alpha(x)\big)>0$.

On the other hand, for every $0<\gamma< \alpha_1\wedge 1$,
\begin{align*}
J_2&\leqslant 2\|u\|_{\infty}\|l_R\|_{\infty}^{1-\gamma}
\int_{\{|z|>1\}}\frac{|l_R(x+z)-l_R(x)|^{\gamma}}{|z|^{d+\alpha(x)}}\,dz\leqslant \frac{C\|u\|_{\infty}}{R^{\gamma}}\int_{\{|z|>1\}}
|z|^{-d-\alpha(x)+\gamma}\,dz\leqslant C\|u\|_{\infty}R^{-\gamma}.
\end{align*}
According to the argument above, it is easy to verify that
$$
|{\mathcal L} l_R(x)|\leqslant CR^{-\gamma}.
$$

Combining all the estimates above yields
\begin{equation} \begin{split}
g_R^{\delta}(t,x)\leqslant C(\varepsilon,u)R^{-\gamma}-\delta.
\end{split}
\end{equation}

Now we are going to verify that for every fixed $R$ large enough,
\begin{equation} \sup_{x \in \mathds R^d}u_R^{\delta}(t,x)\leqslant \sup_{x \in \mathds R^d}u_R^{\delta}(\varepsilon,x),\quad t\in (\varepsilon,1].
\end{equation}

Furthermore, from \eqref{t4-3-7a} it is easy to see
\begin{equation*}
 {\mathcal L} u_R^{\delta}(t_0,x_0)=\int_{\mathds R^d}\big(u_R^{\delta}(t_0,x_0+z)+
u_R^{\delta}(t_0,x_0-z)-2u_R^{\delta}(t_0,x_0)\big)\frac{\kappa(x_0,z)}{|z|^{d+\alpha(x_0)}}\,dz\leqslant 0.
\end{equation*}

Combining this with \eqref{t4-3-6a}, we get that for every $R>\big(\frac{2C(\varepsilon,u)}{\delta}\big)^{{1}/{\gamma}}$,
\begin{align*}
 {\mathcal L} u_R^{\delta}(t_0,x_0)+g_R^{\delta}(t_0,x_0)\leqslant -{\delta}/{2},
\end{align*}
which contradicts with \eqref{t4-3-8}.

(iii) We have by \eqref{eq2-1} that
\begin{align*}
u_f(t,x)-f(x)&=\int_{\mathds R^d}p^y(t,x-y)\big(f(y)-f(x)\big)\,dy+
f(x)\left(\int_{\mathds R^d}p^y(t,x-y)\,dy-1\right)\\
&\quad +\int_{\mathds R^d} f(y)\int_0^t\int_{\mathds R^d}p^z(t-s,x-z)q(s,z,y)\,dz\,ds\,dy\\
&=:J_1+J_2+J_3.
\end{align*}

For any $f\in C_{b,u}(\mathds R^d)$ and for every $\varepsilon>0$, there exists
a constant $\delta:=\delta(\varepsilon)>0$ such that $|f(x)-f(y)|<\varepsilon$ for all $x,y \in \mathds R^d$ with
$|x-y|\leqslant \delta$. Thus,
\begin{align*}
|J_1|&\leqslant \int_{\{|y-x|\leqslant \delta\}}p^y(t,x-y)|f(y)-f(x)|\,dy+
\int_{\{|y-x|>\delta\}}p^y(t,x-y)|f(y)-f(x)|\,dy\\
&\leqslant \varepsilon \int_{\mathds R^d}\rho^{y,0}_1(t,x-y)\,dy+
C(\varepsilon)\|f\|_{\infty}\int_{\{|y-x|>\delta\}}\frac{t}{|x-y|^{d+\alpha_1}}\,dy\leqslant C\varepsilon+C(\varepsilon,\delta)t,
\end{align*}
where in the last inequality we have used \eqref{l3-1-1}.
According to \eqref{p4-1-1}, it holds that $\lim_{t \downarrow 0}\sup_{x \in \mathds R^d}|J_2|=0$.
Furthermore, by \eqref{p3-1-1} and \eqref{l3-3-1}, we obtain that for $\gamma<\beta_0^*/{\alpha_2}$ with $\beta^*\in (0,\beta]\cap(0,\alpha_2/2)$,
\begin{align*}
|J_3|&\preceq \|f\|_{\infty}\Bigg[\int_{\mathds R^d}
\int_0^t\int_{\mathds R^d}\rho^{z,0}_1(t-s,x-z)
\Big(\rho^{y,0}_{{(\beta_0^*/\alpha_2)}-\gamma}(s,z-y)+ \rho^{y,\beta_0^*}_{-\gamma}(s,z-y)\Big)\,dz\,ds\,dy\Bigg]\\
&\preceq \|f\|_{\infty}\int_{\mathds R^d}
\Big(\rho^{y,0}_{1+{(\beta_0^*/\alpha_2)}-\gamma}+\rho^{y,\beta_0^*}_{1-\gamma}\Big)(t,x-y)\,dy\preceq t^{{(\beta_0^*/\alpha_2)}-\gamma}\|f\|_{\infty}.
\end{align*}
Combining all the estimates above together, we arrive at
\begin{equation*}
\lim_{t \downarrow 0}\sup_{x \in \mathds R^d}\big|u_f(t,x)-f(x)\big|\leqslant \varepsilon.
\end{equation*}
Since $\varepsilon$ is arbitrary, we know that \eqref{t1-1-3} holds.

\smallskip

(iv) Denote by $C_{b}^{\varepsilon}(\mathds R^d)$ the set of bounded H\"{o}lder continuous functions, and by $C_{b}^{2,\varepsilon}(\mathds R^d)$ the set of bounded twice differentiable functions whose second derivatives are uniformly H\"{o}lder continuous.  We first suppose that $f \in C_{b}^{2,\varepsilon}(\mathds R^d)$. Let
\begin{equation*}
\tilde u_f(t,x):=f(x)+\int_0^t\int_{\mathds R^d}p(s,x,y){\mathcal L} f(y)\,dy\,ds=f(x)+\int_0^t
u_{{\mathcal L} f}(s,x)\,ds.
\end{equation*}
Since ${\mathcal L} f \in C_{b}^{\varepsilon}(\mathds R^d)$, it is easy to see that
\begin{equation*}
\frac{\partial \tilde u_f(t,x)}{\partial t}=\int_{\mathds R^d}p(t,x,y){\mathcal L} f(y)\,dy
=u_{{\mathcal L} f}(t,x),\quad t\in (0,1]
\end{equation*} and
\begin{equation*}
\lim_{t \downarrow 0}\sup_{x\in\mathds R^d}|\tilde u_f(t,x)-f(x)|=0.
\end{equation*}

On the other hand, due to ${\mathcal L} f \in C_{b}^{\varepsilon}(\mathds R^d)$ again, it follows from \eqref{t1-1-2} that
$ {\mathcal L} u_{{\mathcal L} f}(t,x)=\frac{\partial u_{{\mathcal L} f}(t,x)}{\partial t}$. Furthermore, following the
proof of Proposition \ref{t4-1}, we will get
\begin{align*}
\int_0^t \Big|\int_{\mathds R^d} {\mathcal L}^x p^z(t-s,x-z){\mathcal L} f(z)\,dz\Big|\,ds
&\leqslant \int_0^t \Big|\int_{\mathds R^d} {\mathcal L}^z p^z(t-s,x-z){\mathcal L} f(z)\,dz\Big|\,ds\\
&\quad +\int_0^t \Big|\int_{\mathds R^d}( {\mathcal L}^x- {\mathcal L}^z) p^z(t-s,x-z){\mathcal L} f(z)\,dz\Big|\,ds<\infty
\end{align*} and so $$\int_0^t {\mathcal L} u_{{\mathcal L} f}(s,x)\,ds$$ is well defined.
Hence,
\begin{align*}
{\mathcal L}\tilde u_f(t,x)&={\mathcal L} f(x)+\int_0^t
 {\mathcal L} u_{{\mathcal L} f}(s,x)\,ds={\mathcal L} f(x)+\int_0^t \frac{\partial u_{{\mathcal L} f}(s,x)}{\partial s}\,ds\\
&={\mathcal L} f(x)+u_{{\mathcal L} f}(t,x)-{\mathcal L} f(x)=u_{{\mathcal L} f}(t,x),
\end{align*}
where in the third equality we used
$\lim_{t \downarrow 0}\sup_{x\in\mathds R^d}|u_{{\mathcal L} f}(t,x)-{\mathcal L} f(x)|=0$, thanks to \eqref{t1-1-3}.
Therefore, both $u_f$ and $\tilde u_f$ are solutions of the following PDE
\begin{equation} \begin{cases}
\frac{\partial u(t,x)}{\partial t}= {\mathcal L} u(t,x),\\
\lim_{t \downarrow 0}\sup_{x \in \mathds R^d}|u(t,x)-f(x)|=0.
\end{cases}
\end{equation}

Let $w_f(t,x):=u_f(t,x)-\tilde u_f(t,x)$. Then,  \eqref{t4-3-2a} and \eqref{t4-3-1} hold for $w_f$ with $w_f(0,x)\equiv 0$. At the same time, it is easy to verify from \eqref{eq2-1}
that the function $t \mapsto {\mathcal L} w_f(t,x)$ is continuous on $(0,1]$, and that
\eqref{t1-1-7} implies \eqref{t4-3-2} holds for $w_f$. Thus, by Theorem \ref{t4-3}, we have
\begin{equation*}
w_f(t,x)\leqslant w_f(0,x)=0,\quad (t,x)\in (0,1]\times \mathds R^d.
\end{equation*}
Furthermore, applying the argument above to $-w_f$, we finally get that \begin{equation*}
w_f(t,x)\equiv 0,\quad  (t,x)\in (0,1]\times \mathds R^d.
\end{equation*}
Therefore, $u_f(t,x)=\tilde u_f(t,x)$ for any $t \in (0,1]$ and $x \in \mathds R^d$, which further implies that
\begin{equation*}
\int_{\mathds R^d} {\mathcal L} p(t,\cdot,y)(x)f(y)\,dy=\frac{\partial u_f(t,x)}{\partial t}
=\frac{\partial \tilde u_{f}(t,x)}{\partial t}=\int_{\mathds R^d}p(t,x,y){\mathcal L} f(y)\,dy.
\end{equation*}
Thus, \eqref{t1-1-5a} holds. Observe that
\begin{equation*}
u_f(t,x)=\tilde u_f(t,x)=f(x)+\int_0^t u_{{\mathcal L} f}(s,x)\,ds.
\end{equation*}
According to \eqref{t1-1-3}, we arrive at \eqref{t1-1-5b} immediately.
By the standard approximation procedure, we know that \eqref{t1-1-5a} and
\eqref{t1-1-5b} still hold for every $f \in C_{b,u}^2(\mathds R^d)$.

\smallskip

(v) Let $u(t,x)=:\int_{\mathds R^d}p(t,x,y)\,dy$. Then, according to \eqref{t1-1-2} and \eqref{t1-1-3}, we know that
$u$ satisfies the following equation
\begin{equation} \begin{cases}
\frac{\partial u(t,x)}{\partial t}= {\mathcal L} u(t,x),\\
\lim_{t \downarrow 0}\sup_{x \in \mathds R^d}\big|u(t,x)-1\big|=0.
\end{cases}
\end{equation}
At the same time, $v(t,x)\equiv 1$ satisfies the equation \eqref{t1-1-11} above. Note that \eqref{t4-3-2} and the time continuity condition hold for both
$u(t,x)$ and $v(t,x)$. Then, using the same argument as in (iv)  and applying Theorem \ref{t4-3}, we obtain
\begin{equation*}
\int_{\mathds R^d}p(t,x,y)\,dy=u(t,x)=1,\quad (t,x)\in (0,1]\times \mathds R^d,
\end{equation*}
which is \eqref{t1-1-6}.

For every fixed $s \in (0,1)$ and $y \in \mathds R^d$, we define $$u_{s,y}(t,x):=\int_{\mathds R^d}p(t,x,z)p(s,z,y)\,dz.$$
 Again by \eqref{t1-1-2} and \eqref{t1-1-3}, the following equation holds for $u_{s,y}$:
\begin{equation} \begin{cases}
\frac{\partial u_{s,y}(t,x)}{\partial t}= {\mathcal L} u_{s,y}(t,x),\\
\lim_{t \downarrow 0}\sup_{x \in \mathds R^d}|u_{s,y}(t,x)-p(s,x,y)|=0.
\end{cases}
\end{equation}
On the other hand, it is easy to verify that $v_{s,y}(t,x):=p(t+s,x,y)$ satisfies
\eqref{t1-1-12}, and \eqref{t4-3-2} and the time continuity condition hold for both
$u_{s,y}(t,x)$ and $v_{s,y}(t,x)$.  Following the procedure above and applying Theorem \ref{t4-3}, we arrive at
$$\int_{\mathds R^d}p(t,x,z)p(s,z,y)\,dz=u_{s,y}(t,x)=v_{s,y}(t,x)=p(t+s,x,y),$$
which is \eqref{t1-1-5}.

\smallskip

Throughout this part, we will always
suppose that either of two conditions below is satisfied:
\begin{itemize}
\item [(1)] $\kappa(x,z)$ is independent of $z$.
\item [(2)] $\kappa(x,z)$ depends on $z$, and $({\alpha_2}/{\alpha_1})-1<\beta_0^{**}/{\alpha_2},$ where $\beta_0^{**}\in (0,\beta_0]\cap(0,\alpha_2/2).$
\end{itemize}

Second, \eqref{p3-1-2} and \eqref{l3-3-1}  yield that for all $t\in (0,1]$ and $x,y\in\mathds R^d$ with $|x-y|\leqslant 5t^{{1}/{\alpha_2}}$,
\begin{equation} \begin{split}
&\int_0^t \int_{\mathds R^d}
p^z(t-s,x-z)|q(s,z,y)|\,dz\,ds\\
&\preceq\int_0^t \int_{\mathds R^d}\rho^{z,0}_1(t-s,x-z)
\cdot\Big(\rho^{y,0}_{({\beta_0^{**}}/{\alpha_2})-\gamma_2 }+\rho^{y,\beta_0^{**}}_{-\gamma_2 }\Big)(s,z,y)\,dz\,ds\\
&\preceq \rho^{y,\beta_0^{**}}_{1-\gamma_2 }(t,x-y)+\rho^{y,0}_{1+({\beta_0^{**}}/{\alpha_2})-\gamma_2 }(t,x-y)\\
& \preceq
|x-y|^{\beta_0^{**}}t^{-{d}/{\alpha(y)}-\gamma_2 }+t^{-({d}/{\alpha(y)})+({\beta_0^{**}}/{\alpha_2})-\gamma_2 }\preceq t^{-({d}/{\alpha(y)})+({\beta_0^{**}}/{\alpha_2})-\gamma_2 },
\end{split}
\end{equation}
where in the first inequality $\gamma_2: =({\alpha_2}/{\alpha_1})-1+\gamma$ and the fourth inequality
follows from the fact that $|x-y|\leqslant 5t^{{1}/{\alpha_2}}$.

The assumption $({\alpha_2}/{\alpha_1})-1<{\beta_0^{**}}/{\alpha_2}$ ensures that we can choose
$\gamma>0$ small enough such that $\gamma_2 <{\beta_0^{**}}/{\alpha_2}$. Combining \eqref{p4-3-4}
with \eqref{p4-3-3}, \eqref{eq2-1} and \eqref{p4-3-2}, we arrive at that there is a constant $t_0\in(0,1]$ such that for all $t\in (0,t_0]$ and $x,y\in \mathds R^d$ with $|x-y|\leqslant 5(t^{{1}/{\alpha(x)}}\vee t^{{1}/{\alpha(y)}})$,
\begin{equation} p(t,x,y)\succeq t^{-{d}/{\alpha(y)}}\asymp t^{-{d}/{\alpha(x)}}.
\end{equation}

Therefore, according to the Chapman-Kolmogorov equation
\eqref{t1-1-5} and \eqref{pnte}, for every $t\in [t_0,2t_0]$ and $x,y\in \mathds R^d$ with $|x-y|\leqslant
5t^{{1}/{\alpha(x)}}$,
\begin{align*}
p(t,x,y)&=\int_{\mathds R^d}p(t_0,x,z)p(t-t_0,z,y)\,dz\succeq (t-t_0)^{-{d}/{\alpha(y)}}\int_{\{|z-y|\leqslant 5(t-t_0)^{{1}/{\alpha(y)}}\}}
p(t_0,x,z)\,dz\\
&\succeq (t-t_0)^{-{d}/{\alpha(y)}}t_0^{-{d}/{\alpha(x)}}(t-t_0)^{{d}/{\alpha(y)}}\succeq
t^{-{d}/{\alpha(x)}}.
\end{align*}

For any subset $D\subseteq \mathds R^d$, define
\begin{equation*}
\sigma_{D}:=\inf\{t \geqslant 0: X_t \in D\},\qquad \tau_D:=\inf\{t \geqslant 0: X_t \notin D\}.
\end{equation*}

Then, by \eqref{p4-4-0}, for every $0<r<1$, $A>0$ and $x \in \mathds R^d$,
\begin{equation} \begin{split}
\mathds P_x \big(\tau_{B(x,Ar)}\leqslant r^{\alpha(x)}\big)&\leqslant \mathds E_x f_{Ar,x}\big(X_{\tau_{B(x,Ar)}\wedge r^{\alpha(x)}}\big)=\mathds E_x \Big(\int_0^{\tau_{B(x,Ar)}\wedge r^{\alpha(x)}}{\mathcal L} f_{Ar,x}(X_s)\,ds\Big).
\end{split}
\end{equation}

Observe that for every $y \in B(x,Ar)$ and $\lambda>1$,
\begin{align*}
|{\mathcal L} f_{Ar,x}(y)|&\preceq
\int_{\{|z|\leqslant \lambda r\}}|\delta_{f_{Ar,x}}(y;z)|\cdot \frac{dz}{|z|^{d+\alpha(y)}}
+\int_{\{|z|>\lambda r\}}|\delta_{f_{Ar,x}}(y;z)|\cdot \frac{dz}{|z|^{d+\alpha(y)}}\\
&\preceq \frac{\|\nabla^2 f\|_{\infty}}{(Ar)^2}
\int_{\{|z|\leqslant \lambda r\}}|z|^{2-d-\alpha(y)}\,dz+\|f\|_{\infty}
\int_{\{|z|> \lambda r\}}|z|^{-d-\alpha(y)}\,dz\\
&\preceq \bigg(\frac{\|\nabla^2 f\|_{\infty}\lambda^{2-\alpha(y)}}{A^2}+
\frac{\|f\|_{\infty}}{\lambda^{\alpha(y)}}\bigg)\cdot r^{-\alpha(y)}.
\end{align*}

Hence, first taking $\lambda$ large enough and then $A$ large enough, we can find a constant $A_0>0$ such that
\begin{equation*}
|{\mathcal L} f_{A_0r,x}(y)|\leqslant \frac{1}{4}r^{-\alpha(y)}\quad \textrm{for all } y \in B(x,A_0r).
\end{equation*}

Since for every $y \in B(x,A_0r)$ and $r\in (0,1)$,
\begin{align*}
r^{-\alpha(y)}&=r^{-\alpha(x)}r^{-(\alpha(y)-\alpha(x))}\leqslant r^{-|\alpha(x)-\alpha(y)|}r^{-\alpha(x)}\leqslant r^{-C_1(A_0r)^{\beta_0}}r^{-\alpha(x)}\leqslant \exp(C_2|\log r|r^{\beta_0})r^{-\alpha(x)},
\end{align*}
there exists a constant $r_0>0$ small enough such that $r^{-\alpha(y)}\leqslant 2 r^{-\alpha(x)}$ for all
$r \in (0,r_0)$ and $y \in B(x,A_0r)$. Hence, we have for every $r \in (0,r_0)$ and $y\in B(x,A_0r)$,
\begin{equation*}
|{\mathcal L} f_{A_0r,x}(y)|\leqslant \frac{1}{2}r^{-\alpha(x)}.
\end{equation*}

Following the proof of \eqref{l3-2-8}, we know that
$t^{{1}/{\alpha(y)}}\geqslant C_1 t^{{1}/{\alpha(z)}}$ for every $z \in B(y,t^{{1}/{\alpha(y)}}/2)$.
Hence, there exists a constant $0<\lambda_0<1$ such that for all $0<\lambda<\lambda_0$
and $z \in B(y,t^{{1}/{\alpha(y)}}/2)$,
\begin{equation} \begin{split}
&\mathds P_z\big(\tau_{B(z,t^{{1}/{\alpha(y)}}/2)}>\lambda t\big)
\geqslant \mathds P_z\big(\tau_{B(z,{C_1t^{{1}/{\alpha(z)}}}/{2})}>\lambda t\big)\geqslant {1}/{2},
\end{split}
\end{equation}
where the last inequality  follows from \eqref{l4-3-1}.

On the other hand, by the L\'evy system \eqref{p4-4-1}, for $\lambda>0$ small enough and for any $x,y\in \mathds R^d$ with $
|x-y|>5\max\{t^{{1}/{\alpha(x)}},t^{{1}/{\alpha(y)}}\}$,
\begin{equation} \begin{split}
 \mathds P_x\big(\sigma_{B(y,t^{{1}/{\alpha(y)}}/2)}\leqslant \lambda t\big)
&\geqslant \mathds P_x\big(X_{\lambda t \wedge \tau_{B(x,t^{{1}/{\alpha(x)}})}}\in B(y,t^{{1}/{\alpha(y)}}/2)\big)\\
&=\mathds E_x\bigg(\int_0^{\lambda t \wedge \tau_{B(x,t^{{1}/{\alpha(x)}})}}
\int_{B(y,t^{{1}/{\alpha(y)}}/2)}\frac{du}{|X_s-u|^{d+\alpha(X_s)}}\,ds\bigg)\\
&\succeq \lambda t^{1+({d}/{\alpha(y)})}\cdot \inf_{z \in B(x,t^{{1}/{\alpha(x)}})}\frac{1}{|x-y|^{d+\alpha(z)}}
\cdot \mathds P_x\big(\tau_{B(x,t^{{1}/{\alpha(x)}})}\geqslant \lambda t\big)\\
&\succeq \frac{t^{1+({d}/{\alpha(y)})}}{|x-y|^{d+\alpha(x)}},
\end{split}
\end{equation}
where in the first inequality we used the fact that
$|x-y|\geqslant 5\max\{t^{{1}/{\alpha(x)}},t^{{1}/{\alpha(y)}}\}$ implies $B(x,t^{{1}/{\alpha(x)}})\cap
B(y,t^{{1}/{\alpha(y)}}/2)=\emptyset$, the second inequality follows from the fact that
$|z-u|\preceq |x-y|$ for any $z \in B\big(x,t^{{1}/{\alpha(x)}}\big)$
and $u \in B\big(y,t^{{1}/{\alpha(y)}}/2\big)$, and in the last inequality we used
\eqref{l4-3-1} and the fact that for any $x,y,z\in \mathds R^d$ with $|x-y|\geqslant 5t^{{1}/{\alpha(x)}}$ and $z \in
B(x,t^{{1}/{\alpha(x)}})$ and for every $0<t\leqslant 1$,
\begin{align*}
|x-y|^{-d-\alpha(z)}&\succeq |x-y|^{-d-\alpha(x)+C_2|x-z|^{\beta_0}}\succeq t^{C_2t^{{\beta_0}/{\alpha_1}}}|x-y|^{-d-\alpha(x)}\succeq |x-y|^{-d-\alpha(x)}.
\end{align*}
